CREATE TABLE `workflow_instance` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `definition_id` BINARY(16) COMMENT 'Definition version the instance runs on (never changes)',
  `subject_kind` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `subject_id` BINARY(16) NOT NULL,
  `state` VARCHAR(60) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `started_by` BINARY(16) COMMENT 'Actor (user or service identity)',
  `completed_at` DATETIME(6),
  `context` JSON COMMENT 'Workflow variables (no special-category content)',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_workflow_instance_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_workflow_instance_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_workflow_instance_subject_kind_subject_id` (`tenant_id`, `subject_kind`, `subject_id`),
  CONSTRAINT `ck_workflow_instance__status` CHECK (`status` IN ('running', 'waiting', 'completed', 'cancelled', 'failed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[GOV/transaction/internal] Running workflow on a subject record';

CREATE TABLE `workflow_task` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `instance_id` BINARY(16) NOT NULL,
  `step_key` VARCHAR(60) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `assignee_role` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Role code when assigned by role-at-scope',
  `assignee_scope_id` BINARY(16) COMMENT 'Scope of the role assignment',
  `assignee_user_id` BINARY(16) COMMENT 'Resolved user',
  `approval_type` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `due_at` DATETIME(6),
  `reminded_at` DATETIME(6) COMMENT '75% of SLA reminder',
  `escalated_at` DATETIME(6),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `decision` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin,
  `decided_by` BINARY(16),
  `decided_at` DATETIME(6),
  `external_task_ref` VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Linked workspace-messaging task (Zenzap) for two-way sync',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_workflow_task_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_workflow_task_assignee_user_id_status` (`tenant_id`, `assignee_user_id`, `status`),
  KEY `ix_workflow_task_instance_id` (`tenant_id`, `instance_id`),
  CONSTRAINT `ck_workflow_task__approval_type` CHECK (`approval_type` IS NULL OR `approval_type` IN ('single', 'any_of', 'all_of', 'sequential')),
  CONSTRAINT `ck_workflow_task__status` CHECK (`status` IN ('open', 'claimed', 'completed', 'escalated', 'reassigned', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[GOV/queue/internal] Human task in a workflow (assignee resolved from role-at-scope, SLA, escalation)';

CREATE TABLE `workflow_transition` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `instance_id` BINARY(16) NOT NULL,
  `from_state` VARCHAR(60) CHARACTER SET ascii COLLATE ascii_bin,
  `to_state` VARCHAR(60) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `actor` BINARY(16),
  `reason` TEXT,
  `occurred_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_workflow_transition_instance_id` (`tenant_id`, `instance_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[GOV/event/internal] Transition of a workflow instance (append-only; mirrored in the audit trail)';

-- ============================================================================
-- Domain IAM — Identity, access, permissions and service identities
-- ============================================================================

CREATE TABLE `access_review` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `grant_id` BINARY(16) NOT NULL,
  `reviewer_id` BINARY(16) NOT NULL,
  `decision` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `reason` VARCHAR(500) COLLATE utf8mb4_0900_ai_ci,
  `reviewed_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_access_review_grant_id` (`tenant_id`, `grant_id`),
  KEY `ix_access_review_reviewer_id` (`tenant_id`, `reviewer_id`),
  CONSTRAINT `ck_access_review__decision` CHECK (`decision` IN ('keep', 'reduce', 'revoke', 'escalate'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[IAM/event/internal] Periodic access review decision on a grant';

CREATE TABLE `app_user` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `username` VARCHAR(254) COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Sign-in name (e-mail or issued username)',
  `display_name` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `phone` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'E.164; used for OTP and magic links',
  `person_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Linked master record type',
  `person_id` BINARY(16) COMMENT 'learner, guardian or staff id (registry)',
  `idp` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `idp_subject` VARCHAR(255) COLLATE utf8mb4_0900_ai_ci COMMENT 'Subject at the federated IdP',
  `password_hash` VARCHAR(255) COLLATE utf8mb4_0900_ai_ci COMMENT 'Argon2id (local accounts only)',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `locked_until` DATETIME(6) COMMENT 'Lockout after 5 failures in 10 minutes',
  `failed_attempts` SMALLINT NOT NULL DEFAULT 0,
  `last_sign_in_at` DATETIME(6),
  `preferences` JSON COMMENT 'Language, text size, theme, density, digest, briefing horizons',
  `deactivated_at` DATETIME(6) COMMENT 'Automatic from the HR leaving date',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_app_user_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_app_user_username` (`tenant_id`, `username`),
  UNIQUE KEY `uq_app_user_idp_idp_subject` (`tenant_id`, `idp`, `idp_subject`),
  KEY `ix_app_user_person_kind_person_id` (`tenant_id`, `person_kind`, `person_id`),
  CONSTRAINT `ck_app_user__person_kind` CHECK (`person_kind` IS NULL OR `person_kind` IN ('learner', 'guardian', 'staff', 'provider_person', 'applicant', 'visitor')),
  CONSTRAINT `ck_app_user__idp` CHECK (`idp` IN ('local', 'gov_sso', 'entra', 'google', 'magic_link', 'otp')),
  CONSTRAINT `ck_app_user__status` CHECK (`status` IN ('invited', 'active', 'locked', 'suspended', 'deactivated'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[IAM/master/confidential] Sign-in identity (a person may also be a learner, guardian or staff member) — Administrator 360 root';

CREATE TABLE `break_glass_grant` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `user_id` BINARY(16) NOT NULL,
  `scope_id` BINARY(16) NOT NULL,
  `reason` TEXT NOT NULL,
  `starts_at` DATETIME(6) NOT NULL,
  `ends_at` DATETIME(6) NOT NULL,
  `dpo_notified_at` DATETIME(6),
  `reviewed_by` BINARY(16),
  `reviewed_at` DATETIME(6),
  `review_outcome` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_break_glass_grant_user_id` (`tenant_id`, `user_id`),
  KEY `ix_break_glass_grant_scope_id` (`tenant_id`, `scope_id`),
  KEY `ix_break_glass_grant_reviewed_by` (`tenant_id`, `reviewed_by`),
  CONSTRAINT `ck_break_glass_grant__review_outcome` CHECK (`review_outcome` IS NULL OR `review_outcome` IN ('keep', 'reduce', 'revoke', 'escalate')),
  CONSTRAINT `ck_break_glass_grant__window` CHECK (ends_at > starts_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[IAM/transaction/restricted] Time-boxed elevated emergency access (DPO and data owner notified; reviewed within 24 h)';

CREATE TABLE `credential_reset` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `user_id` BINARY(16) NOT NULL,
  `purpose` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `token_hash` BINARY(32) NOT NULL,
  `requested_ip` VARBINARY(16),
  `expires_at` DATETIME(6) NOT NULL,
  `used_at` DATETIME(6),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_credential_reset_token_hash` (`tenant_id`, `token_hash`),
  KEY `ix_credential_reset_user_id` (`tenant_id`, `user_id`),
  CONSTRAINT `ck_credential_reset__purpose` CHECK (`purpose` IN ('password_reset', 'magic_link', 'mfa_recovery'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[IAM/transaction/confidential] Password-reset or magic-link token (hashed, single use, short expiry; generic responses)';

CREATE TABLE `mfa_factor` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `user_id` BINARY(16) NOT NULL,
  `factor_type` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `label` VARCHAR(80) COLLATE utf8mb4_0900_ai_ci,
  `secret_enc` VARBINARY(1024) COMMENT 'Envelope-encrypted secret. TOTP seed or WebAuthn credential (public key and id)',
  `credential_id` VARCHAR(255) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'WebAuthn credential id',
  `last_used_at` DATETIME(6),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_mfa_factor_user_id` (`tenant_id`, `user_id`),
  CONSTRAINT `ck_mfa_factor__factor_type` CHECK (`factor_type` IN ('totp', 'passkey', 'sms_otp', 'email_otp')),
  CONSTRAINT `ck_mfa_factor__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[IAM/master/restricted] Multi-factor authentication factor (TOTP, FIDO2 passkey, SMS/e-mail OTP fallback)';

CREATE TABLE `purpose_code` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'registration, safeguarding, investigation, transfer_query, exam_integrity, child_missing_education …',
  `label` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `requires_reason_text` BOOLEAN NOT NULL DEFAULT FALSE,
  `allowed_roles` JSON COMMENT 'Role codes permitted to use the purpose',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_purpose_code_code` (`tenant_id`, `code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[IAM/reference/public] Purpose recorded when restricted fields are revealed or special-category records opened';

CREATE TABLE `role` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `code` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'TCH, DSL, STA, PROP, REV …',
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `clearance` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Highest classification the role normally receives',
  `is_builtin` BOOLEAN NOT NULL DEFAULT FALSE,
  `cloned_from_id` BINARY(16),
  `created_by_clearance` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Custom role may never exceed its creator''s clearance',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_role_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_role_code` (`tenant_id`, `code`),
  KEY `ix_role_cloned_from_id` (`tenant_id`, `cloned_from_id`),
  CONSTRAINT `ck_role__clearance` CHECK (`clearance` IN ('public', 'internal', 'confidential', 'restricted', 'special')),
  CONSTRAINT `ck_role__created_by_clearance` CHECK (`created_by_clearance` IS NULL OR `created_by_clearance` IN ('public', 'internal', 'confidential', 'restricted', 'special')),
  CONSTRAINT `ck_role__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[IAM/config/internal] Role template (41 built-in roles plus REV, ACG, OPF; built-ins cloneable, never editable)';

CREATE TABLE `role_grant` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `user_id` BINARY(16) NOT NULL,
  `role_id` BINARY(16) NOT NULL,
  `scope_id` BINARY(16) NOT NULL,
  `clearance_cap` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Narrows the role clearance for this grant',
  `granted_by` BINARY(16),
  `review_due_on` DATE COMMENT 'Access review',
  `delegation_of_id` BINARY(16) COMMENT 'Delegated from another grant (Administrator 360 delegations)',
  `supervised_until` DATE COMMENT 'Time-limited supervised exception approved by the head while mandatory checks are pending (FR-STF-03)',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `valid_from` DATE NOT NULL COMMENT 'Effective from (inclusive) — history: effective',
  `valid_to` DATE COMMENT 'Effective to (inclusive); NULL = open-ended — history: effective',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_role_grant_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_role_grant_user_id_status` (`tenant_id`, `user_id`, `status`),
  KEY `ix_role_grant_role_id` (`tenant_id`, `role_id`),
  KEY `ix_role_grant_scope_id` (`tenant_id`, `scope_id`),
  KEY `ix_role_grant_granted_by` (`tenant_id`, `granted_by`),
  KEY `ix_role_grant_delegation_of_id` (`tenant_id`, `delegation_of_id`),
  CONSTRAINT `ck_role_grant__clearance_cap` CHECK (`clearance_cap` IS NULL OR `clearance_cap` IN ('public', 'internal', 'confidential', 'restricted', 'special')),
  CONSTRAINT `ck_role_grant__status` CHECK (`status` IN ('active', 'inactive', 'retired')),
  CONSTRAINT `ck_role_grant__valid` CHECK (valid_to IS NULL OR valid_to >= valid_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[IAM/link/internal] Role granted to a user at a scope (role-at-scope), with clearance cap and access review date';

CREATE TABLE `role_permission` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `role_id` BINARY(16) NOT NULL,
  `permission` VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'resource:action, e.g. learner:view, learner.nin:reveal, certificate:issue',
  `abac_condition` JSON COMMENT 'own_classes, own_children, assigned_cases, assigned_inspections, own_placements',
  `field_scope` JSON COMMENT 'Restricted/special fields this permission reveals',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_role_permission_role_id_permission` (`tenant_id`, `role_id`, `permission`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[IAM/config/internal] Permission granted by a role (resource:action with optional ABAC condition)';

CREATE TABLE `service_identity` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `owner_user_id` BINARY(16) NOT NULL,
  `owner_grant_id` BINARY(16) NOT NULL COMMENT 'Grant the identity acts under',
  `allowed_tools` JSON COMMENT 'Declared typed commands (agents) or API scopes (clients)',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `paused_at` DATETIME(6) COMMENT 'Kill switch',
  `paused_by` BINARY(16),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_service_identity_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_service_identity_owner_user_id` (`tenant_id`, `owner_user_id`),
  KEY `ix_service_identity_owner_grant_id` (`tenant_id`, `owner_grant_id`),
  KEY `ix_service_identity_paused_by` (`tenant_id`, `paused_by`),
  CONSTRAINT `ck_service_identity__kind` CHECK (`kind` IN ('agent', 'api_client', 'integration', 'system_job')),
  CONSTRAINT `ck_service_identity__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[IAM/master/internal] Non-human principal — automation agent, integration client or system job — bound to a human owner''s grant';

CREATE TABLE `user_pin` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `user_id` BINARY(16) NOT NULL,
  `target_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `target_ref` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Page id, record reference or saved-view id',
  `label` VARCHAR(120) COLLATE utf8mb4_0900_ai_ci,
  `sort_order` SMALLINT NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_user_pin_user_id` (`tenant_id`, `user_id`),
  CONSTRAINT `ck_user_pin__target_kind` CHECK (`target_kind` IN ('page', 'record', 'saved_view'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[IAM/config/internal] Pinned page, record or saved view of a user (navigation v2)';

CREATE TABLE `user_session` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `user_id` BINARY(16) NOT NULL,
  `session_hash` BINARY(32) NOT NULL COMMENT 'SHA-256 of the session token',
  `active_grant_id` BINARY(16) COMMENT 'Role-at-scope chosen in AUT-03',
  `device_label` VARCHAR(120) COLLATE utf8mb4_0900_ai_ci,
  `is_trusted_device` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Trusted for 30 days',
  `ip` VARBINARY(16),
  `user_agent` VARCHAR(400) COLLATE utf8mb4_0900_ai_ci,
  `mfa_at` DATETIME(6),
  `started_at` DATETIME(6) NOT NULL,
  `last_seen_at` DATETIME(6) NOT NULL,
  `expires_at` DATETIME(6) NOT NULL,
  `revoked_at` DATETIME(6),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_user_session_session_hash` (`tenant_id`, `session_hash`),
  KEY `ix_user_session_user_id` (`tenant_id`, `user_id`),
  KEY `ix_user_session_active_grant_id` (`tenant_id`, `active_grant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[IAM/transaction/confidential] Server-side session (idle timeout 30 min for restricted/special roles, 8 h otherwise)';

-- ============================================================================
-- Domain MDM — Master data management, identity matching and data quality
-- ============================================================================

CREATE TABLE `data_quality_issue` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `rule_key` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `dimension` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `record_kind` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `record_id` BINARY(16),
  `detail` VARCHAR(1000) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `severity` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `detected_at` DATETIME(6) NOT NULL,
  `owner_user_id` BINARY(16),
  `resolved_at` DATETIME(6),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_data_quality_issue_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_data_quality_issue_rule_key_status` (`tenant_id`, `rule_key`, `status`),
  CONSTRAINT `ck_data_quality_issue__dimension` CHECK (`dimension` IN ('completeness', 'uniqueness', 'validity', 'timeliness', 'consistency', 'verification')),
  CONSTRAINT `ck_data_quality_issue__severity` CHECK (`severity` IN ('critical', 'high', 'moderate', 'info')),
  CONSTRAINT `ck_data_quality_issue__status` CHECK (`status` IN ('open', 'in_progress', 'resolved', 'dismissed', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[MDM/queue/internal] Open data-quality issue on a record (validation failure, probable duplicate, stale dataset, conflict)';

CREATE TABLE `data_quality_rule` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `rule_key` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `dimension` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `entity` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'CEDA entity checked',
  `expression` TEXT NOT NULL COMMENT 'Rule DSL or SQL template over the semantic layer',
  `severity` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `version` INT UNSIGNED NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_data_quality_rule_scope_node_id_rule_key_version` (`tenant_id`, `scope_node_id`, `rule_key`, `version`),
  CONSTRAINT `ck_data_quality_rule__dimension` CHECK (`dimension` IN ('completeness', 'uniqueness', 'validity', 'timeliness', 'consistency', 'verification')),
  CONSTRAINT `ck_data_quality_rule__severity` CHECK (`severity` IN ('critical', 'high', 'moderate', 'info')),
  CONSTRAINT `ck_data_quality_rule__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[MDM/config/internal] Data-quality rule feeding the DQI components (completeness, uniqueness, validity, timeliness, consistency, verification)';

CREATE TABLE `dataset_freshness` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `dataset` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `last_received_at` DATETIME(6),
  `expected_interval_hours` SMALLINT NOT NULL,
  `is_stale` BOOLEAN NOT NULL DEFAULT FALSE,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_dataset_freshness_institution_id_dataset` (`tenant_id`, `institution_id`, `dataset`),
  KEY `ix_dataset_freshness_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_dataset_freshness__dataset` CHECK (`dataset` IN ('enrolment', 'attendance', 'staffing', 'curriculum_coverage', 'results', 'safety', 'fees', 'compliance', 'finance', 'registers'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[MDM/projection/internal] Last data received per institution per dataset (stale institutions shown, not hidden)';

CREATE TABLE `external_identifier` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `person_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `person_id` BINARY(16) NOT NULL COMMENT 'learner, guardian, staff or provider_person id (polymorphic)',
  `scheme` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'NG-NIN, WAEC-CAND, NECO-CAND, JAMB-REG, TRCN, UPN, INST-ID …',
  `value_hmac` BINARY(32) NOT NULL COMMENT 'HMAC-SHA-256 lookup of value',
  `value_enc` VARBINARY(1024) NOT NULL COMMENT 'Envelope-encrypted value. Identifier value — envelope-encrypted per tenant and scheme',
  `value_last4` CHAR(4) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Last four characters of value for masked display',
  `value_national_hmac` BINARY(32) COMMENT 'National lookup token (federation key) — NIN only, for cross-state matching without exchanging the NIN (CR-002)',
  `issuer` VARCHAR(120) COLLATE utf8mb4_0900_ai_ci COMMENT 'Issuing body where not implied by the scheme',
  `verified_at` DATETIME(6),
  `verified_via` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_external_identifier_person_kind_person_id` (`tenant_id`, `person_kind`, `person_id`),
  KEY `ix_external_identifier_scheme_value_hmac` (`tenant_id`, `scheme`, `value_hmac`),
  KEY `ix_external_identifier_scheme_value_national_hmac` (`tenant_id`, `scheme`, `value_national_hmac`),
  CONSTRAINT `ck_external_identifier__person_kind` CHECK (`person_kind` IN ('learner', 'guardian', 'staff', 'provider_person', 'applicant', 'visitor')),
  CONSTRAINT `ck_external_identifier__verified_via` CHECK (`verified_via` IS NULL OR `verified_via` IN ('nimc', 'registrar', 'exam_body', 'trcn', 'cac', 'manual')),
  CONSTRAINT `ck_external_identifier__status` CHECK (`status` IN ('unverified', 'verified', 'mismatch', 'revoked'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[MDM/master/restricted] Authorised external identifier of a person (NIN, exam candidate number, UPN, TRCN number …)';

CREATE TABLE `identity_verification` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `person_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `person_id` BINARY(16) NOT NULL,
  `scheme` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `channel` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `requested_by` BINARY(16) NOT NULL COMMENT 'User or service identity',
  `purpose_code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `outcome` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `match_detail` JSON COMMENT 'Field-level agreement (name, DOB) — no source photo or address stored',
  `provider_ref` VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Gateway transaction reference',
  `occurred_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_identity_verification_tenant` (`tenant_id`),
  CONSTRAINT `ck_identity_verification__person_kind` CHECK (`person_kind` IN ('learner', 'guardian', 'staff', 'provider_person', 'applicant', 'visitor')),
  CONSTRAINT `ck_identity_verification__channel` CHECK (`channel` IN ('nimc', 'registrar', 'exam_body', 'trcn', 'cac', 'manual')),
  CONSTRAINT `ck_identity_verification__outcome` CHECK (`outcome` IN ('match', 'partial_match', 'no_match', 'manual_review', 'error'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[MDM/event/restricted] Identity verification attempt against a national source (NIMC NIN, TRCN, CAC) — result only, not the source data';

CREATE TABLE `match_pair_decision` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `entity_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `record_a_id` BINARY(16) NOT NULL,
  `record_b_id` BINARY(16) NOT NULL,
  `decision` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `model_version` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_match_pair_decision_entity_kind_record_a_id_record_b_id` (`tenant_id`, `entity_kind`, `record_a_id`, `record_b_id`),
  CONSTRAINT `ck_match_pair_decision__entity_kind` CHECK (`entity_kind` IN ('learner', 'guardian', 'staff', 'institution', 'provider', 'supplier', 'course', 'programme')),
  CONSTRAINT `ck_match_pair_decision__decision` CHECK (`decision` IN ('same', 'different', 'unsure'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[MDM/event/internal] Remembered steward decision on a pair (suppresses re-raising; trains matching weights)';

CREATE TABLE `match_review` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `entity_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `candidate_id` BINARY(16) NOT NULL COMMENT 'Incoming or newer record',
  `existing_id` BINARY(16) NOT NULL COMMENT 'Existing master record',
  `score` DECIMAL(7,6) NOT NULL COMMENT '0.80–0.98 probable band; ≥ 0.98 auto-linked (still logged)',
  `evidence` JSON NOT NULL COMMENT 'Field comparisons, blocking keys, model version',
  `source` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `assigned_to` BINARY(16),
  `decision` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `decision_reason` VARCHAR(500) COLLATE utf8mb4_0900_ai_ci,
  `decided_by` BINARY(16),
  `decided_at` DATETIME(6),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_match_review_entity_kind_candidate_id_existing_id` (`tenant_id`, `entity_kind`, `candidate_id`, `existing_id`),
  KEY `ix_match_review_assigned_to` (`tenant_id`, `assigned_to`),
  KEY `ix_match_review_decided_by` (`tenant_id`, `decided_by`),
  CONSTRAINT `ck_match_review__entity_kind` CHECK (`entity_kind` IN ('learner', 'guardian', 'staff', 'institution', 'provider', 'supplier', 'course', 'programme')),
  CONSTRAINT `ck_match_review__source` CHECK (`source` IN ('registration', 'import', 'transfer', 'digitisation', 'exam_import', 'application', 'nightly_scan')),
  CONSTRAINT `ck_match_review__decision` CHECK (`decision` IS NULL OR `decision` IN ('same', 'different', 'unsure')),
  CONSTRAINT `ck_match_review__status` CHECK (`status` IN ('open', 'in_progress', 'resolved', 'dismissed', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[MDM/queue/restricted] Probable-duplicate pair awaiting or holding a steward decision';

CREATE TABLE `merge_journal` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `entity_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `survivor_id` BINARY(16) NOT NULL,
  `merged_id` BINARY(16) NOT NULL COMMENT 'Becomes an alias that still resolves',
  `survivorship` JSON NOT NULL COMMENT 'Field → chosen source and rule',
  `repointed` JSON NOT NULL COMMENT 'Table → count of references re-pointed',
  `approved_by` BINARY(16) NOT NULL,
  `second_approver_id` BINARY(16) COMMENT 'Required for records with certificates/results',
  `merged_at` DATETIME(6) NOT NULL,
  `unmerge_deadline` DATE NOT NULL,
  `unmerged_at` DATETIME(6),
  `unmerged_by` BINARY(16),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_merge_journal_entity_kind_merged_id` (`tenant_id`, `entity_kind`, `merged_id`),
  KEY `ix_merge_journal_approved_by` (`tenant_id`, `approved_by`),
  KEY `ix_merge_journal_second_approver_id` (`tenant_id`, `second_approver_id`),
  KEY `ix_merge_journal_unmerged_by` (`tenant_id`, `unmerged_by`),
  CONSTRAINT `ck_merge_journal__entity_kind` CHECK (`entity_kind` IN ('learner', 'guardian', 'staff', 'institution', 'provider', 'supplier', 'course', 'programme')),
  CONSTRAINT `ck_merge_journal__four_eyes` CHECK (second_approver_id IS NULL OR second_approver_id <> approved_by)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[MDM/event/restricted] Merge of two master records with survivorship and re-pointed references (un-merge within 90 days)';

-- ============================================================================
-- Domain INS — Institution 360, state institution register, licensing, inspection and compliance
-- ============================================================================

CREATE TABLE `campus` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `address` JSON,
  `location` POINT SRID 4326,
  `is_main` BOOLEAN NOT NULL DEFAULT FALSE,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_campus_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_campus_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_campus_institution_id` (`tenant_id`, `institution_id`),
  CONSTRAINT `ck_campus__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INS/master/internal] Campus / site / branch of an institution';

CREATE TABLE `compliance_requirement` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `requirement_key` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `category` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `applies_to` JSON NOT NULL COMMENT 'Institution categories, levels, ownership',
  `evidence_required` TEXT,
  `renewal_months` SMALLINT,
  `version` INT UNSIGNED NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_compliance_requirement_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_compliance_requirement_scope_node_id_requirement_key_version` (`tenant_id`, `scope_node_id`, `requirement_key`, `version`),
  CONSTRAINT `ck_compliance_requirement__category` CHECK (`category` IN ('fire', 'health_safety', 'structural', 'food_hygiene', 'transport', 'statutory_certification', 'data_protection', 'safeguarding')),
  CONSTRAINT `ck_compliance_requirement__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INS/config/internal] Compliance requirement inherited down the policy hierarchy (fire, health and safety, certifications with expiry)';

CREATE TABLE `compliance_status` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `requirement_id` BINARY(16) NOT NULL,
  `evidence_document_id` BINARY(16),
  `certified_on` DATE,
  `expires_on` DATE,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_compliance_status_institution_id_requirement_id` (`tenant_id`, `institution_id`, `requirement_id`),
  KEY `ix_compliance_status_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_compliance_status_requirement_id` (`tenant_id`, `requirement_id`),
  CONSTRAINT `ck_compliance_status__status` CHECK (`status` IN ('compliant', 'attention_required', 'overdue', 'critical'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INS/transaction/internal] Status of one compliance requirement at one institution (Compliant, Attention required, Overdue, Critical)';

CREATE TABLE `corrective_action` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
