  `source_id` BINARY(16) NOT NULL,
  `description` TEXT NOT NULL,
  `owner_user_id` BINARY(16),
  `due_on` DATE NOT NULL,
  `evidence_document_ids` JSON,
  `verified_by` BINARY(16),
  `verified_at` DATETIME(6),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_corrective_action_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_corrective_action_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_corrective_action_institution_id` (`tenant_id`, `institution_id`),
  KEY `ix_corrective_action_owner_user_id` (`tenant_id`, `owner_user_id`),
  KEY `ix_corrective_action_verified_by` (`tenant_id`, `verified_by`),
  CONSTRAINT `ck_corrective_action__source_kind` CHECK (`source_kind` IN ('inspection_finding', 'approval_condition', 'compliance', 'curriculum_alert', 'alert', 'intervention_workflow')),
  CONSTRAINT `ck_corrective_action__status` CHECK (`status` IN ('open', 'plan_submitted', 'plan_approved', 'in_progress', 'evidence_submitted', 'verified', 'overdue', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INS/transaction/confidential] Corrective action plan item (from findings, approval conditions, compliance or curriculum alerts)';

CREATE TABLE `facility_check` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `campus_id` BINARY(16),
  `check_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `performed_on` DATE NOT NULL,
  `performed_by` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci,
  `result` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `certificate_document_id` BINARY(16),
  `expires_on` DATE,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_facility_check_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_facility_check_institution_id` (`tenant_id`, `institution_id`),
  KEY `ix_facility_check_campus_id` (`tenant_id`, `campus_id`),
  CONSTRAINT `ck_facility_check__result` CHECK (`result` IN ('pass', 'pass_with_actions', 'fail'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INS/transaction/internal] Fire inspection, health and safety check or certification with expiry (compliance centre evidence)';

CREATE TABLE `health_index_policy` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `version` INT UNSIGNED NOT NULL,
  `weights` JSON NOT NULL COMMENT 'Indicator → weight (attendance, progress, exam outcomes … resource utilisation)',
  `targets` JSON NOT NULL COMMENT 'Indicator → normalisation target',
  `bands` JSON NOT NULL COMMENT 'strong ≥ 80, adequate 65–79, concern 50–64, critical < 50',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `effective_from` DATE NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_health_index_policy_scope_node_id_version` (`tenant_id`, `scope_node_id`, `version`),
  CONSTRAINT `ck_health_index_policy__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INS/config/internal] Versioned health-index weights, targets and bands (decomposable score, P8)';

CREATE TABLE `inspection` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `programme_id` BINARY(16),
  `provider_application_id` BINARY(16) COMMENT 'Approval inspection',
  `scheduled_on` DATE NOT NULL,
  `lead_inspector_id` BINARY(16),
  `risk_score` DECIMAL(7,3),
  `briefing` JSON COMMENT 'Briefing pack snapshot (coverage, gaps, data, history, complaints)',
  `overall_judgement` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `report_document_id` BINARY(16),
  `visited_location` POINT SRID 4326 COMMENT 'GPS captured on site',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_inspection_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_inspection_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_inspection_institution_id` (`tenant_id`, `institution_id`),
  KEY `ix_inspection_programme_id` (`tenant_id`, `programme_id`),
  KEY `ix_inspection_provider_application_id` (`tenant_id`, `provider_application_id`),
  KEY `ix_inspection_lead_inspector_id` (`tenant_id`, `lead_inspector_id`),
  CONSTRAINT `ck_inspection__kind` CHECK (`kind` IN ('approval', 'routine', 'monitoring', 'follow_up', 'thematic', 'renewal')),
  CONSTRAINT `ck_inspection__status` CHECK (`status` IN ('planned', 'scheduled', 'in_progress', 'report_draft', 'report_approved', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INS/transaction/confidential] Inspection 360 — approval, routine, monitoring or follow-up inspection';

CREATE TABLE `inspection_finding` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `inspection_id` BINARY(16) NOT NULL,
  `area` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `judgement` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `evidence` TEXT NOT NULL,
  `evidence_document_ids` JSON,
  `requires_action` BOOLEAN NOT NULL DEFAULT FALSE,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_inspection_finding_inspection_id` (`tenant_id`, `inspection_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INS/transaction/confidential] Finding recorded during an inspection (with photos and GPS evidence)';

CREATE TABLE `inspection_programme` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `period_start` DATE NOT NULL,
  `period_end` DATE NOT NULL,
  `method` JSON COMMENT 'Weights: health index, compliance, alerts, time since last inspection',
  `approved_by` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_inspection_programme_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_inspection_programme_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_inspection_programme_approved_by` (`tenant_id`, `approved_by`),
  CONSTRAINT `ck_inspection_programme__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INS/config/internal] Risk-based inspection programme for a period, for inspectorate approval';

CREATE TABLE `institution` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_code` VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'INS-<country>-NNNNNN',
  `gov_reg_no` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Government registration number, e.g. AB/SS/0412',
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `short_name` VARCHAR(80) COLLATE utf8mb4_0900_ai_ci,
  `category` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'ECCDE, primary, JSS, SSS, technical college, college of education, polytechnic, university, nursing, non-formal …',
  `ownership` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'federal, state, lga, private, faith, community, ngo',
  `is_public` BOOLEAN NOT NULL COMMENT 'Derived from ownership; drives the financing channel',
  `operating_tenant_id` BINARY(16) NOT NULL COMMENT 'Tenant whose ops zone runs the institution (state for public; provider tenant for private)',
  `provider_id` BINARY(16) COMMENT 'Private provider (proprietor organisation)',
  `network_scope_id` BINARY(16) COMMENT 'Optional network layer',
  `lga_scope_id` BINARY(16) NOT NULL COMMENT 'LGA the institution belongs to',
  `levels` JSON NOT NULL COMMENT 'Education levels offered',
  `day_boarding` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `gender_intake` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `address` JSON NOT NULL COMMENT 'Structured address (street, town, LGA, state, postcode)',
  `location` POINT SRID 4326 COMMENT 'WGS84; NOT NULL once surveyed (500 m / 5 km duplicate checks)',
  `location_class` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'urban, peri-urban, rural (comparison context)',
  `capacity` INT UNSIGNED,
  `head_staff_id` BINARY(16),
  `website` VARCHAR(2048) CHARACTER SET ascii COLLATE ascii_bin,
  `phone` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin,
  `email` VARCHAR(254) COLLATE utf8mb4_0900_ai_ci,
  `onboarding_status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Not yet onboarded, Onboarding, Live, Suspended, Closed',
  `regulatory_status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'approved, approved_with_conditions, regularising, suspended, closed, unregistered',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `merged_into` BINARY(16) COMMENT 'Alias after amalgamation',
  `is_regularisation` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Existing unregistered institution brought into compliance',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_institution_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_institution_institution_code` (`tenant_id`, `institution_code`),
  UNIQUE KEY `uq_institution_gov_reg_no` (`tenant_id`, `gov_reg_no`),
  KEY `ix_institution_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_institution_lga_scope_id` (`tenant_id`, `lga_scope_id`),
  KEY `ix_institution_ownership_category` (`tenant_id`, `ownership`, `category`),
  KEY `ix_institution_name` (`tenant_id`, `name`),
  KEY `ix_institution_provider_id` (`tenant_id`, `provider_id`),
  KEY `ix_institution_network_scope_id` (`tenant_id`, `network_scope_id`),
  KEY `ix_institution_head_staff_id` (`tenant_id`, `head_staff_id`),
  KEY `ix_institution_merged_into` (`tenant_id`, `merged_into`),
  CONSTRAINT `ck_institution__day_boarding` CHECK (`day_boarding` IS NULL OR `day_boarding` IN ('day', 'boarding', 'mixed')),
  CONSTRAINT `ck_institution__gender_intake` CHECK (`gender_intake` IS NULL OR `gender_intake` IN ('mixed', 'boys', 'girls')),
  CONSTRAINT `ck_institution__location_class` CHECK (`location_class` IS NULL OR `location_class` IN ('urban', 'peri_urban', 'rural')),
  CONSTRAINT `ck_institution__onboarding_status` CHECK (`onboarding_status` IN ('not_onboarded', 'onboarding', 'live', 'suspended', 'closed')),
  CONSTRAINT `ck_institution__regulatory_status` CHECK (`regulatory_status` IN ('approved', 'approved_with_conditions', 'regularising', 'suspended', 'closed', 'unregistered', 'public_owned')),
  CONSTRAINT `ck_institution__status` CHECK (`status` IN ('proposed', 'active', 'suspended', 'closed', 'merged'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INS/master/internal] Institution 360 master (public and private, every level)';

CREATE TABLE `institution_change_request` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `field_changes` JSON NOT NULL COMMENT '[{field, from, to}]',
  `reason` TEXT NOT NULL,
  `evidence_document_id` BINARY(16),
  `requested_by` BINARY(16) NOT NULL,
  `decided_by` BINARY(16),
  `decided_at` DATETIME(6),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_institution_change_request_scope` (`tenant_id`, `scope_node_id`),
