) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[PVT/master/public] Approval certificate of a private institution (signed, QR-verifiable, levels, capacity, conditions, expiry)';

