  KEY `ix_closure_case_sanction_id` (`tenant_id`, `sanction_id`),
  KEY `ix_closure_case_lga_officer_id` (`tenant_id`, `lga_officer_id`),
  CONSTRAINT `ck_closure_case__status` CHECK (`status` IN ('open', 'in_progress', 'on_hold', 'closed', 'transferred'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[PVT/transaction/confidential] Learner protection case when a private institution is suspended or closed (LGA tracks re-enrolment)';

CREATE TABLE `provider` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `legal_name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `trading_name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci,
  `cac_number` VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Corporate Affairs Commission registration',
  `tin` VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Tax identification number',
  `provider_tenant_id` BINARY(16) COMMENT 'Private tenant created on first approval',
  `registered_address` JSON NOT NULL,
  `phone` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin,
  `email` VARCHAR(254) COLLATE utf8mb4_0900_ai_ci,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_provider_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_provider_cac_number` (`tenant_id`, `cac_number`),
  KEY `ix_provider_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_provider__status` CHECK (`status` IN ('registered', 'applicant', 'approved', 'suspended', 'closed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[PVT/master/confidential] Private education provider (proprietor organisation) — Provider 360';

CREATE TABLE `provider_application` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `provider_id` BINARY(16) NOT NULL,
  `application_number` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `proposed_institution` JSON NOT NULL COMMENT 'Name, levels, location, capacity, curricula, fee schedule, staffing plan',
  `proposed_location` POINT SRID 4326 COMMENT 'Map pin (duplicate check within 500 m)',
  `institution_id` BINARY(16) COMMENT 'Existing or created institution',
  `federal_approval` JSON COMMENT 'NUC / NBTE / NCCE / MDCN / NMCN evidence for tertiary and medical (FR-PVT-117)',
  `completeness` DECIMAL(6,3) COMMENT 'Share of checklist items evidenced',
  `submitted_at` DATETIME(6),
  `desk_review_due_on` DATE COMMENT '10 working days',
  `inspection_due_on` DATE COMMENT '20 working days',
  `decision` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `decision_reasons` TEXT,
  `decided_by` BINARY(16),
  `second_approver_id` BINARY(16) COMMENT 'Four-eyes decision',
  `decided_at` DATETIME(6),
  `appeal_route` VARCHAR(500) COLLATE utf8mb4_0900_ai_ci,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_provider_application_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_provider_application_application_number` (`tenant_id`, `application_number`),
  KEY `ix_provider_application_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_provider_application_provider_id` (`tenant_id`, `provider_id`),
  KEY `ix_provider_application_institution_id` (`tenant_id`, `institution_id`),
  KEY `ix_provider_application_decided_by` (`tenant_id`, `decided_by`),
  KEY `ix_provider_application_second_approver_id` (`tenant_id`, `second_approver_id`),
  CONSTRAINT `ck_provider_application__kind` CHECK (`kind` IN ('new', 'regularisation', 'renewal', 'variation')),
  CONSTRAINT `ck_provider_application__decision` CHECK (`decision` IS NULL OR `decision` IN ('approve', 'approve_with_conditions', 'defer', 'refuse')),
  CONSTRAINT `ck_provider_application__status` CHECK (`status` IN ('draft', 'submitted', 'fee_pending', 'desk_review', 'query_raised', 'inspection', 'decision', 'approved', 'refused', 'deferred', 'withdrawn', 'appealed')),
  CONSTRAINT `ck_provider_application__four_eyes` CHECK (second_approver_id IS NULL OR decided_by IS NULL OR second_approver_id <> decided_by)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[PVT/transaction/confidential] Application for approval (new, regularisation or renewal) of one or more proposed institutions';

CREATE TABLE `provider_person` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `provider_id` BINARY(16) NOT NULL,
  `user_id` BINARY(16) COMMENT 'Account of the proprietor (PROP role)',
  `given_name` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `family_name` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `role` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `nin_verified` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'External identifier held in external_identifier',
  `ownership_share` DECIMAL(6,3),
  `valid_from` DATE NOT NULL COMMENT 'Effective from (inclusive) — history: effective',
  `valid_to` DATE COMMENT 'Effective to (inclusive); NULL = open-ended — history: effective',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_provider_person_provider_id` (`tenant_id`, `provider_id`),
  KEY `ix_provider_person_user_id` (`tenant_id`, `user_id`),
  CONSTRAINT `ck_provider_person__role` CHECK (`role` IN ('proprietor', 'director', 'company_secretary', 'head_designate')),
  CONSTRAINT `ck_provider_person__valid` CHECK (valid_to IS NULL OR valid_to >= valid_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[PVT/link/restricted] Proprietor or director of a provider (identity verified by NIN)';

CREATE TABLE `reg_dataset_definition` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `dataset` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `fields` JSON NOT NULL COMMENT 'Fields included',
  `frequency` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `version` INT UNSIGNED NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_reg_dataset_definition_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_reg_dataset_definition_scope_node_id_dataset_version` (`tenant_id`, `scope_node_id`, `dataset`, `version`),
  CONSTRAINT `ck_reg_dataset_definition__dataset` CHECK (`dataset` IN ('enrolment', 'attendance', 'staffing', 'curriculum_coverage', 'results', 'safety', 'fees', 'compliance', 'finance', 'registers')),
  CONSTRAINT `ck_reg_dataset_definition__frequency` CHECK (`frequency` IN ('live', 'daily', 'weekly', 'termly', 'per_series', 'per_session', 'as_occurs')),
  CONSTRAINT `ck_reg_dataset_definition__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[PVT/config/internal] Regulatory dataset that private institutions share with the state (configured per country/state, MFS §10.5)';

CREATE TABLE `reg_snapshot` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `dataset` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `definition_id` BINARY(16) NOT NULL,
  `as_of` DATETIME(6) NOT NULL,
  `payload` JSON NOT NULL COMMENT 'Aggregates and permitted identities only',
  `payload_hash` BINARY(32) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_reg_snapshot_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_reg_snapshot_institution_id_dataset_as_of` (`tenant_id`, `institution_id`, `dataset`, `as_of`),
  KEY `ix_reg_snapshot_definition_id` (`tenant_id`, `definition_id`),
  CONSTRAINT `ck_reg_snapshot__dataset` CHECK (`dataset` IN ('enrolment', 'attendance', 'staffing', 'curriculum_coverage', 'results', 'safety', 'fees', 'compliance', 'finance', 'registers'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[PVT/snapshot/confidential] Regulatory dataset delivery from a private institution (read-only to the regulator)';

CREATE TABLE `regulatory_fee` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `provider_id` BINARY(16) NOT NULL,
  `application_id` BINARY(16),
  `fee_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `amount_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `revenue_code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'State revenue code',
  `payment_reference` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Remita RRR',
  `paid_at` DATETIME(6),
  `receipt_number` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_regulatory_fee_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_regulatory_fee_provider_id` (`tenant_id`, `provider_id`),
  KEY `ix_regulatory_fee_application_id` (`tenant_id`, `application_id`),
  CONSTRAINT `ck_regulatory_fee__fee_kind` CHECK (`fee_kind` IN ('application', 'inspection', 'approval', 'renewal', 'late_renewal')),
  CONSTRAINT `ck_regulatory_fee__status` CHECK (`status` IN ('due', 'paid', 'waived', 'refunded'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[PVT/transaction/confidential] State regulatory fee (application, inspection, approval, renewal) — separate from the operator subscription';

CREATE TABLE `sanction` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `step` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `grounds` TEXT NOT NULL,
  `evidence_document_ids` JSON NOT NULL,
  `blocks_admissions` BOOLEAN NOT NULL DEFAULT FALSE,
  `blocks_exam_entries` BOOLEAN NOT NULL DEFAULT FALSE,
  `decided_by` BINARY(16) NOT NULL,
  `effective_on` DATE NOT NULL,
  `appeal_status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `lifted_on` DATE,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sanction_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_sanction_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_sanction_institution_id` (`tenant_id`, `institution_id`),
  KEY `ix_sanction_decided_by` (`tenant_id`, `decided_by`),
  CONSTRAINT `ck_sanction__step` CHECK (`step` IN ('warning', 'conditions', 'admissions_suspended', 'suspension', 'closure')),
  CONSTRAINT `ck_sanction__appeal_status` CHECK (`appeal_status` IS NULL OR `appeal_status` IN ('none', 'lodged', 'upheld', 'dismissed')),
  CONSTRAINT `ck_sanction__status` CHECK (`status` IN ('proposed', 'approved', 'in_effect', 'appealed', 'lifted', 'upheld'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[PVT/transaction/confidential] Sanction step on a private institution (warning → conditions → suspension of admissions → suspension → closure) with appeal';

-- ============================================================================
-- Domain LRN — Learner 360, state enrolment register, transfer and Education Passport
-- ============================================================================

CREATE TABLE `cme_referral` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `learner_id` BINARY(16) NOT NULL,
  `enrolment_id` BINARY(16) NOT NULL,
  `lga_scope_id` BINARY(16) NOT NULL,
  `reason` VARCHAR(500) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `assigned_to` BINARY(16),
  `outcome` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `closed_at` DATETIME(6),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_cme_referral_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_cme_referral_learner_id` (`tenant_id`, `learner_id`),
  KEY `ix_cme_referral_enrolment_id` (`tenant_id`, `enrolment_id`),
  KEY `ix_cme_referral_lga_scope_id` (`tenant_id`, `lga_scope_id`),
  KEY `ix_cme_referral_assigned_to` (`tenant_id`, `assigned_to`),
  CONSTRAINT `ck_cme_referral__outcome` CHECK (`outcome` IS NULL OR `outcome` IN ('located_enrolled', 'located_not_enrolled', 'moved_out_of_state', 'not_located', 'deceased')),
  CONSTRAINT `ck_cme_referral__status` CHECK (`status` IN ('open', 'in_progress', 'on_hold', 'closed', 'transferred'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[LRN/transaction/confidential] Child-missing-education referral to the LGA attendance desk (compulsory-age leaver with unknown destination)';

CREATE TABLE `enrolment` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `learner_id` BINARY(16) NOT NULL,
  `institution_id` BINARY(16) NOT NULL,
  `operating_tenant_id` BINARY(16) NOT NULL COMMENT 'Tenant whose ops zone holds the operational record',
  `education_level` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `programme_id` BINARY(16),
  `class_group_id` BINARY(16) COMMENT 'Ops-zone class (arm) for the session',
  `cohort_label` VARCHAR(60) COLLATE utf8mb4_0900_ai_ci COMMENT 'Intake cohort, e.g. 2026/2027 ND1',
  `is_primary` BOOLEAN NOT NULL DEFAULT TRUE,
  `basis` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `start_on` DATE NOT NULL,
  `end_on` DATE,
  `leaving_reason` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `destination` JSON COMMENT 'Destination institution, employment, unknown …',
  `is_over_capacity_approved` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Head approval recorded when capacity is exceeded',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `active_primary_key` BINARY(16) GENERATED ALWAYS AS (IF(`status` = 'active' AND `is_primary`, `learner_id`, NULL)) STORED COMMENT '= learner_id when status active and is_primary, else NULL (one active primary enrolment)',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_enrolment_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_enrolment_active_primary_key` (`tenant_id`, `active_primary_key`),
  KEY `ix_enrolment_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_enrolment_learner_id_start_on` (`tenant_id`, `learner_id`, `start_on`),
  KEY `ix_enrolment_institution_id_status` (`tenant_id`, `institution_id`, `status`),
  KEY `ix_enrolment_programme_id` (`tenant_id`, `programme_id`),
  CONSTRAINT `ck_enrolment__basis` CHECK (`basis` IN ('admission', 'transfer', 'promotion', 're_enrolment', 'temporary', 'repeat')),
  CONSTRAINT `ck_enrolment__status` CHECK (`status` IN ('pending', 'active', 'completed', 'withdrawn', 'transferred', 'suspended')),
  CONSTRAINT `ck_enrolment__dates` CHECK (end_on IS NULL OR end_on >= start_on)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[LRN/transaction/confidential] State enrolment register — learner enrolled at an institution (and level, programme) for a period';

CREATE TABLE `external_exam_record` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `learner_id` BINARY(16) NOT NULL,
  `exam_body` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `exam_year` SMALLINT NOT NULL,
  `candidate_number_hmac` BINARY(32) COMMENT 'Lookup token of the candidate number',
  `results` JSON NOT NULL COMMENT 'Subject → grade, as verified',
  `verified_at` DATETIME(6) NOT NULL,
  `verification_ref` VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `holder_consents_display` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Shown on verification results only with consent',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_external_exam_record_learner_id` (`tenant_id`, `learner_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[LRN/master/confidential] Verified external examination result linked to Learner 360 (WAEC, NECO, NABTEB, JAMB) — linked, never re-issued';

CREATE TABLE `historical_record_import` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `learner_id` BINARY(16) NOT NULL,
  `enrolment_id` BINARY(16) NOT NULL,
  `source_institution_id` BINARY(16),
  `source_system` VARCHAR(120) COLLATE utf8mb4_0900_ai_ci,
  `datasets` JSON NOT NULL COMMENT 'Results, attendance summary, SEND/safeguarding handover flags',
  `received_at` DATETIME(6) NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_historical_record_import_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_historical_record_import_learner_id` (`tenant_id`, `learner_id`),
  KEY `ix_historical_record_import_enrolment_id` (`tenant_id`, `enrolment_id`),
  KEY `ix_historical_record_import_source_institution_id` (`tenant_id`, `source_institution_id`),
  CONSTRAINT `ck_historical_record_import__status` CHECK (`status` IN ('uploaded', 'mapped', 'validating', 'validated', 'matching', 'staged', 'committed', 'rolled_back', 'failed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[LRN/transaction/confidential] Authorised historical record received from a previous institution at enrolment (no re-supply by families)';

CREATE TABLE `learner` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `global_learner_id` CHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'LRN-NNNN-NNNN-CC, assigned at creation from the state''s leased block, never reused',
  `legal_given_name` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `legal_middle_names` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci,
  `legal_family_name` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `preferred_name` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci,
  `name_phonetic` VARCHAR(120) COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Double Metaphone keys + Nigerian name-variant keys for blocking',
  `date_of_birth` DATE NOT NULL,
  `dob_precision` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'day' COMMENT 'Displaced and historic learners may have month or year only',
  `sex` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `nationality` CHAR(2) CHARACTER SET ascii COLLATE ascii_bin,
  `state_of_origin` VARCHAR(6) CHARACTER SET ascii COLLATE ascii_bin,
  `home_languages` JSON,
  `photo_document_id` BINARY(16) COMMENT 'Records zone; restricted',
  `is_historic` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Created from a digitised archive (FR-DOC-108)',
  `is_minimal_documentation` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Temporary enrolment (IDP camps); identity matching reconciles later',
  `identity_verified_level` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'unverified',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `merged_into` BINARY(16),
  `deceased_on` DATE,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_learner_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_learner_global_learner_id` (`tenant_id`, `global_learner_id`),
  KEY `ix_learner_legal_family_name_date_of_birth` (`tenant_id`, `legal_family_name`, `date_of_birth`),
  KEY `ix_learner_name_phonetic` (`tenant_id`, `name_phonetic`),
  KEY `ix_learner_date_of_birth` (`tenant_id`, `date_of_birth`),
  KEY `ix_learner_merged_into` (`tenant_id`, `merged_into`),
  CONSTRAINT `ck_learner__dob_precision` CHECK (`dob_precision` IN ('day', 'month', 'year')),
  CONSTRAINT `ck_learner__identity_verified_level` CHECK (`identity_verified_level` IN ('unverified', 'document_seen', 'nin_verified', 'archive_verified')),
  CONSTRAINT `ck_learner__status` CHECK (`status` IN ('registered', 'active', 'left', 'deceased', 'merged'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[LRN/master/confidential] Learner 360 master — one row per person, lifelong';

CREATE TABLE `learner_transfer` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `learner_id` BINARY(16) NOT NULL,
  `from_enrolment_id` BINARY(16) NOT NULL,
  `to_institution_id` BINARY(16) COMMENT 'NULL when leaving the state (exchange)',
  `to_enrolment_id` BINARY(16),
  `exchange_transfer_id` BINARY(16) COMMENT 'Cross-state or international records exchange',
  `requested_by` BINARY(16) NOT NULL,
  `effective_on` DATE NOT NULL,
  `records_package` JSON COMMENT 'Datasets transferred per policy',
  `dsl_handover_due_on` DATE,
  `dsl_acknowledged_at` DATETIME(6) COMMENT 'Safeguarding file acknowledged by receiving DSL',
  `senco_acknowledged_at` DATETIME(6) COMMENT 'SEND file acknowledged by receiving SENCO',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_learner_transfer_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_learner_transfer_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_learner_transfer_learner_id` (`tenant_id`, `learner_id`),
  KEY `ix_learner_transfer_from_enrolment_id` (`tenant_id`, `from_enrolment_id`),
  KEY `ix_learner_transfer_to_institution_id` (`tenant_id`, `to_institution_id`),
  KEY `ix_learner_transfer_to_enrolment_id` (`tenant_id`, `to_enrolment_id`),
  KEY `ix_learner_transfer_exchange_transfer_id` (`tenant_id`, `exchange_transfer_id`),
  KEY `ix_learner_transfer_requested_by` (`tenant_id`, `requested_by`),
  CONSTRAINT `ck_learner_transfer__status` CHECK (`status` IN ('requested', 'accepted', 'records_sent', 'handover_pending', 'completed', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[LRN/transaction/confidential] Transfer of a learner between institutions (within or across tenants and states), with DSL/SENCO handover acknowledgement';

CREATE TABLE `passport_entry` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `learner_id` BINARY(16) NOT NULL,
  `entry_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source_kind` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source_id` BINARY(16) NOT NULL COMMENT 'Certificate, badge award, competency record, training completion … (soft)',
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `issuer_name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci,
  `awarded_on` DATE,
  `credential` JSON COMMENT 'Open Badges 3.0 / W3C VC 2.0 document when issued',
  `is_verified` BOOLEAN NOT NULL DEFAULT FALSE,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_passport_entry_learner_id_source_kind_source_id` (`tenant_id`, `learner_id`, `source_kind`, `source_id`),
  CONSTRAINT `ck_passport_entry__entry_kind` CHECK (`entry_kind` IN ('qualification', 'certificate', 'transcript', 'badge', 'competency', 'credit', 'cpd', 'digital_skill', 'guidance'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[LRN/projection/confidential] Education Passport entry — qualification, certificate, badge, competency, credit, CPD or digital-skills milestone';

CREATE TABLE `passport_share` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `learner_id` BINARY(16) NOT NULL,
  `recipient_name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `recipient_email` VARCHAR(254) COLLATE utf8mb4_0900_ai_ci,
  `entries` JSON NOT NULL COMMENT 'Passport entries included',
  `token_hash` BINARY(32) NOT NULL,
  `expires_at` DATETIME(6) NOT NULL,
  `revoked_at` DATETIME(6),
  `view_count` INT UNSIGNED NOT NULL DEFAULT 0,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_passport_share_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_passport_share_token_hash` (`tenant_id`, `token_hash`),
  KEY `ix_passport_share_learner_id` (`tenant_id`, `learner_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[LRN/transaction/confidential] Consented, time-limited, revocable share of a learner''s Education Passport';

CREATE TABLE `passport_view` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `share_id` BINARY(16) NOT NULL,
  `viewed_at` DATETIME(6) NOT NULL,
  `ip_country` CHAR(2) CHARACTER SET ascii COLLATE ascii_bin,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_passport_view_share_id` (`tenant_id`, `share_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[LRN/event/confidential] Verification log of a passport share (holder sees who verified)';

-- ============================================================================
-- Domain FAM — Family 360, guardians, contacts, contact restrictions and consent
-- ============================================================================

CREATE TABLE `guardian` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `given_name` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `family_name` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `title` VARCHAR(30) COLLATE utf8mb4_0900_ai_ci,
  `name_phonetic` VARCHAR(120) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `phone` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'E.164; inbound WhatsApp matching uses phone_hmac in channel contacts',
  `email` VARCHAR(254) COLLATE utf8mb4_0900_ai_ci,
  `preferred_language` VARCHAR(35) CHARACTER SET ascii COLLATE ascii_bin,
  `preferred_channel` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `address` JSON,
  `user_id` BINARY(16) COMMENT 'Parent portal account',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `merged_into` BINARY(16),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_guardian_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_guardian_phone` (`tenant_id`, `phone`),
  KEY `ix_guardian_user_id` (`tenant_id`, `user_id`),
  KEY `ix_guardian_merged_into` (`tenant_id`, `merged_into`),
  CONSTRAINT `ck_guardian__preferred_channel` CHECK (`preferred_channel` IS NULL OR `preferred_channel` IN ('in_app', 'push', 'sms', 'whatsapp', 'email', 'voice', 'ussd', 'workspace', 'web', 'post')),
  CONSTRAINT `ck_guardian__status` CHECK (`status` IN ('active', 'inactive', 'merged', 'deceased'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FAM/master/confidential] Parent/Guardian 360 master';

CREATE TABLE `learner_guardian` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `learner_id` BINARY(16) NOT NULL,
  `guardian_id` BINARY(16) NOT NULL,
  `relationship` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `has_parental_responsibility` BOOLEAN NOT NULL,
  `contact_priority` SMALLINT,
  `lives_with` BOOLEAN,
  `is_contact_restricted` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Detail held in the vault (contact_restriction)',
  `is_authorised_collector` BOOLEAN NOT NULL DEFAULT FALSE,
  `is_payer` BOOLEAN NOT NULL DEFAULT FALSE,
  `valid_from` DATE NOT NULL COMMENT 'Effective from (inclusive) — history: effective',
  `valid_to` DATE COMMENT 'Effective to (inclusive); NULL = open-ended — history: effective',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_learner_guardian_learner_id_guardian_id_valid_from` (`tenant_id`, `learner_id`, `guardian_id`, `valid_from`),
  KEY `ix_learner_guardian_guardian_id` (`tenant_id`, `guardian_id`),
  CONSTRAINT `ck_learner_guardian__valid` CHECK (valid_to IS NULL OR valid_to >= valid_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FAM/link/confidential] Relationship between a learner and a guardian (parental responsibility, priority, lives-with, restriction flag)';

-- ============================================================================
-- Domain STF — Staff / Teacher 360, authorisations, HR, cover, recruitment, CPD, training and payroll
-- ============================================================================

CREATE TABLE `professional_registration_check` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `qualification_id` BINARY(16) NOT NULL,
  `register` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `outcome` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `checked_at` DATETIME(6) NOT NULL,
  `provider_ref` VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_professional_registration_check_qualification_id` (`tenant_id`, `qualification_id`),
  CONSTRAINT `ck_professional_registration_check__outcome` CHECK (`outcome` IN ('match', 'partial_match', 'no_match', 'manual_review', 'error'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[STF/event/confidential] Verification of a professional registration with its register (TRCN, MDCN, NMCN …)';

CREATE TABLE `staff` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `staff_number` VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'STF-NNNN-NNNN with check digit',
  `given_name` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `middle_names` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci,
  `family_name` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `name_phonetic` VARCHAR(120) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `date_of_birth` DATE,
  `sex` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `phone` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin,
  `email` VARCHAR(254) COLLATE utf8mb4_0900_ai_ci,
  `user_id` BINARY(16),
  `is_historic` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Created from a digitised personal file',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `merged_into` BINARY(16),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_staff_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_staff_staff_number` (`tenant_id`, `staff_number`),
  KEY `ix_staff_user_id` (`tenant_id`, `user_id`),
  KEY `ix_staff_merged_into` (`tenant_id`, `merged_into`),
  CONSTRAINT `ck_staff__status` CHECK (`status` IN ('onboarding', 'active', 'leaver', 'merged'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[STF/master/confidential] Staff / Teacher 360 master (one person, many posts)';

CREATE TABLE `staff_post` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `staff_id` BINARY(16) NOT NULL,
  `institution_id` BINARY(16) NOT NULL,
  `org_unit_id` BINARY(16),
  `job_title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `staff_category` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'teaching, non_teaching, lecturer, graduate_assistant …',
  `academic_rank` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Professor, Senior Lecturer, Lecturer I … (load policy)',
  `grade_step` VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin,
  `contract` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `fte` DECIMAL(4,2) NOT NULL,
  `employer_scope_id` BINARY(16) COMMENT 'e.g. SUBEB, TESCOM, the private provider',
  `line_manager_staff_id` BINARY(16),
  `is_temporary` BOOLEAN NOT NULL DEFAULT FALSE,
  `leaving_reason` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `valid_from` DATE NOT NULL COMMENT 'Effective from (inclusive) — history: effective',
  `valid_to` DATE COMMENT 'Effective to (inclusive); NULL = open-ended — history: effective',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_staff_post_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_staff_post_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_staff_post_staff_id` (`tenant_id`, `staff_id`),
  KEY `ix_staff_post_institution_id` (`tenant_id`, `institution_id`),
  KEY `ix_staff_post_org_unit_id` (`tenant_id`, `org_unit_id`),
  KEY `ix_staff_post_employer_scope_id` (`tenant_id`, `employer_scope_id`),
  KEY `ix_staff_post_line_manager_staff_id` (`tenant_id`, `line_manager_staff_id`),
  CONSTRAINT `ck_staff_post__contract` CHECK (`contract` IN ('permanent', 'fixed_term', 'part_time', 'adjunct', 'visiting', 'nysc', 'volunteer', 'graduate_assistant')),
  CONSTRAINT `ck_staff_post__valid` CHECK (valid_to IS NULL OR valid_to >= valid_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[STF/link/confidential] Post held by a staff member at an institution (employer, unit, title, grade, contract, FTE, line manager)';

CREATE TABLE `staff_qualification` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `staff_id` BINARY(16) NOT NULL,
  `kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `subject_id` BINARY(16) COMMENT 'For teaching authorisations',
  `subject_area_code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Tertiary specialism (subject area)',
  `levels` JSON,
  `issuer` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'TRCN, university, professional body',
  `reference` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin,
  `issued_on` DATE,
  `expires_on` DATE,
  `verification` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `verified_by` BINARY(16),
  `document_id` BINARY(16) COMMENT 'Certificate scan (records zone)',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_staff_qualification_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_staff_qualification_staff_id_kind` (`tenant_id`, `staff_id`, `kind`),
  KEY `ix_staff_qualification_subject_id` (`tenant_id`, `subject_id`),
  KEY `ix_staff_qualification_expires_on` (`tenant_id`, `expires_on`),
  KEY `ix_staff_qualification_verified_by` (`tenant_id`, `verified_by`),
  CONSTRAINT `ck_staff_qualification__kind` CHECK (`kind` IN ('degree', 'certificate', 'registration', 'teaching_authorisation', 'specialism', 'check')),
  CONSTRAINT `ck_staff_qualification__verification` CHECK (`verification` IN ('unverified', 'pending', 'verified', 'failed', 'expired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[STF/master/confidential] Qualification, professional registration, teaching authorisation (subject × level) or check, with expiry and verification';

-- ============================================================================
-- Domain ACA — Academic structure — calendars, subjects, programmes, qualifications, classes, departments and courses
-- ============================================================================

CREATE TABLE `academic_period` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `parent_id` BINARY(16),
  `kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `institution_types` JSON COMMENT 'Calendars differ by institution type',
  `starts_on` DATE NOT NULL,
  `ends_on` DATE NOT NULL,
  `teaching_days` SMALLINT COMMENT 'After closures',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_academic_period_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_academic_period_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_academic_period_parent_id` (`tenant_id`, `parent_id`),
  CONSTRAINT `ck_academic_period__kind` CHECK (`kind` IN ('session', 'term', 'semester', 'half_term', 'billing_period')),
  CONSTRAINT `ck_academic_period__status` CHECK (`status` IN ('active', 'inactive', 'retired')),
  CONSTRAINT `ck_academic_period__dates` CHECK (ends_on >= starts_on)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ACA/master/internal] Session, term, semester or half-term of a calendar (state calendar inherited by institutions)';

CREATE TABLE `calendar_event` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `period_id` BINARY(16) NOT NULL,
  `kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `starts_on` DATE NOT NULL,
  `ends_on` DATE NOT NULL,
  `reduces_teaching_days` BOOLEAN NOT NULL DEFAULT FALSE,
  `is_remote_mode` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Closure switches classes to LMS remote mode',
  `exception_id` BINARY(16),
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_calendar_event_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_calendar_event_period_id` (`tenant_id`, `period_id`),
  KEY `ix_calendar_event_exception_id` (`tenant_id`, `exception_id`),
  CONSTRAINT `ck_calendar_event__kind` CHECK (`kind` IN ('holiday', 'closure', 'exam_window', 'event', 'inset_day', 'mid_term_break'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ACA/transaction/internal] Closure, holiday, exam window or event on a calendar (school closures recalculate compliance with an automatic exception)';

CREATE TABLE `course` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `department_id` BINARY(16) NOT NULL,
  `subject_area_id` BINARY(16),
  `subject_id` BINARY(16),
  `code` VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'e.g. COM 214, GST 111',
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `units` DECIMAL(4,1) NOT NULL,
  `course_level` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `semester_no` SMALLINT,
  `is_service_course` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Taught to other departments (GST)',
  `is_compulsory` BOOLEAN NOT NULL DEFAULT TRUE,
  `benchmark_ref` VARCHAR(60) CHARACTER SET ascii COLLATE ascii_bin,
  `outline_document_id` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_course_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_course_department_id_code` (`tenant_id`, `department_id`, `code`),
  KEY `ix_course_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_course_subject_area_id` (`tenant_id`, `subject_area_id`),
  KEY `ix_course_subject_id` (`tenant_id`, `subject_id`),
  CONSTRAINT `ck_course__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ACA/master/public] Course 360 catalogue entry owned by a department (code, units, level, semester, prerequisites, benchmark)';

CREATE TABLE `department` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `org_unit_id` BINARY(16) NOT NULL COMMENT 'The department''s node in the organisation structure',
  `faculty_org_unit_id` BINARY(16),
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `hod_staff_id` BINARY(16),
  `acting_hod_staff_id` BINARY(16),
  `load_policy` JSON COMMENT 'Maximum contact hours per rank',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_department_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_department_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_department_institution_id` (`tenant_id`, `institution_id`),
  KEY `ix_department_org_unit_id` (`tenant_id`, `org_unit_id`),
  KEY `ix_department_faculty_org_unit_id` (`tenant_id`, `faculty_org_unit_id`),
  KEY `ix_department_hod_staff_id` (`tenant_id`, `hod_staff_id`),
  KEY `ix_department_acting_hod_staff_id` (`tenant_id`, `acting_hod_staff_id`),
  CONSTRAINT `ck_department__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ACA/master/internal] Department 360 — academic department of a post-secondary institution';

CREATE TABLE `programme` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) COMMENT 'NULL for national programmes',
  `department_id` BINARY(16),
  `code` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `qualification_id` BINARY(16),
  `delivery_mode` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'on_campus',
  `programme_family` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Health-profession family (medicine, nursing, pharmacy …)',
  `professional_body_id` BINARY(16),
  `duration_terms` SMALLINT,
  `rules` JSON NOT NULL COMMENT 'Credits, CGPA, progression, classification scheme',
  `accreditation_status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `accreditation_expires_on` DATE,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_programme_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_programme_scope_node_id_code` (`tenant_id`, `scope_node_id`, `code`),
  KEY `ix_programme_institution_id` (`tenant_id`, `institution_id`),
  KEY `ix_programme_department_id` (`tenant_id`, `department_id`),
  KEY `ix_programme_qualification_id` (`tenant_id`, `qualification_id`),
  KEY `ix_programme_professional_body_id` (`tenant_id`, `professional_body_id`),
  CONSTRAINT `ck_programme__delivery_mode` CHECK (`delivery_mode` IN ('on_campus', 'distance', 'online', 'blended', 'continuing')),
  CONSTRAINT `ck_programme__accreditation_status` CHECK (`accreditation_status` IS NULL OR `accreditation_status` IN ('full', 'interim', 'denied', 'expired', 'not_required')),
  CONSTRAINT `ck_programme__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ACA/master/public] Programme 360 (qualification-bearing programmes, national or institutional)';

CREATE TABLE `programme_component` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `programme_id` BINARY(16) NOT NULL,
  `course_id` BINARY(16) NOT NULL,
  `programme_level` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin COMMENT '100L, ND1, Year 2',
  `semester_no` SMALLINT,
  `credits` DECIMAL(4,1) NOT NULL,
  `is_core` BOOLEAN NOT NULL,
  `prerequisite_course_ids` JSON COMMENT 'Cycle-checked on save',
  `valid_from` DATE NOT NULL COMMENT 'Effective from (inclusive) — history: effective',
  `valid_to` DATE COMMENT 'Effective to (inclusive); NULL = open-ended — history: effective',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_programme_component_programme_id_course_id_valid_from` (`tenant_id`, `programme_id`, `course_id`, `valid_from`),
  KEY `ix_programme_component_course_id` (`tenant_id`, `course_id`),
  CONSTRAINT `ck_programme_component__valid` CHECK (valid_to IS NULL OR valid_to >= valid_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ACA/link/public] Course or module within a programme (credits, core/elective, prerequisites — cycle-checked)';

CREATE TABLE `qualification` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `code` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `awarding_body` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `framework_level` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin,
  `award_rules` JSON NOT NULL COMMENT 'Evaluated by the eligibility engine',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_qualification_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_qualification_scope_node_id_code` (`tenant_id`, `scope_node_id`, `code`),
  CONSTRAINT `ck_qualification__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ACA/master/public] Qualification 360 (FSLC, BECE, SSC, NTC, NCE, ND, HND, B.Sc. …) with award rules';

CREATE TABLE `stream_combination_rule` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
