  `is_mandatory_core` BOOLEAN NOT NULL DEFAULT FALSE,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_subject_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_subject_scope_node_id_code` (`tenant_id`, `scope_node_id`, `code`),
  CONSTRAINT `ck_subject__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ACA/master/public] Subject 360 master (country master list plus institution courses)';

CREATE TABLE `subject_area` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `department_id` BINARY(16) NOT NULL,
  `code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `benchmark` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `benchmark_area_code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_subject_area_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_subject_area_department_id_code` (`tenant_id`, `department_id`, `code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ACA/master/public] Discipline area of a department mapped to the national benchmark (NUC CCMAS, NBTE, NCCE)';

-- ============================================================================
-- Domain CUR — Curriculum 360, adoption, teaching chain evidence and zero-gap coverage assurance
-- ============================================================================

CREATE TABLE `curriculum` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `code` VARCHAR(48) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'e.g. NG-NERDC-MATH-JSS',
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `framework` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'national, state, cambridge, ib, pearson, competency, institutional',
  `subject_id` BINARY(16),
  `levels` JSON NOT NULL,
  `authority` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'NERDC, State MoE, NBTE, NCCE, NUC …',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_curriculum_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_curriculum_scope_node_id_code` (`tenant_id`, `scope_node_id`, `code`),
  KEY `ix_curriculum_subject_id` (`tenant_id`, `subject_id`),
  CONSTRAINT `ck_curriculum__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CUR/master/public] Curriculum 360 master (national, state, international or institutional framework)';

CREATE TABLE `curriculum_adoption` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `version_id` BINARY(16) NOT NULL,
  `education_level` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `cohort_start_year` SMALLINT,
  `is_additional` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Approved institution addition (Cambridge, IB, faith studies)',
  `resolved_by` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `valid_from` DATE NOT NULL COMMENT 'Effective from (inclusive) — history: effective',
  `valid_to` DATE COMMENT 'Effective to (inclusive); NULL = open-ended — history: effective',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_curriculum_adoption_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_curriculum_adoption_institution_id_education_level` (`tenant_id`, `institution_id`, `education_level`),
  KEY `ix_curriculum_adoption_version_id` (`tenant_id`, `version_id`),
  CONSTRAINT `ck_curriculum_adoption__resolved_by` CHECK (`resolved_by` IN ('automatic', 'state_adaptation', 'institution_addition', 'exception')),
  CONSTRAINT `ck_curriculum_adoption__valid` CHECK (valid_to IS NULL OR valid_to >= valid_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CUR/link/internal] Which curriculum version applies to which institution, level, cohort and period (resolved automatically)';

CREATE TABLE `curriculum_node` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `version_id` BINARY(16) NOT NULL,
  `parent_id` BINARY(16),
  `node_code` VARCHAR(48) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Unique within the version',
  `kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `statement` TEXT NOT NULL,
  `requirement` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'mandatory, optional, recommended, restricted',
  `is_state_addition` BOOLEAN NOT NULL DEFAULT FALSE,
  `min_hours` DECIMAL(6,1),
  `is_assessment_required` BOOLEAN NOT NULL DEFAULT FALSE,
  `teacher_requirements` JSON COMMENT 'Required qualification and specialism',
  `resource_requirements` JSON,
  `term_hint` SMALLINT COMMENT 'Suggested term for scheme-of-work drafting',
  `sort_key` INT NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_curriculum_node_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_curriculum_node_version_id_node_code` (`tenant_id`, `version_id`, `node_code`),
  KEY `ix_curriculum_node_parent_id` (`tenant_id`, `parent_id`),
  CONSTRAINT `ck_curriculum_node__kind` CHECK (`kind` IN ('subject', 'strand', 'theme', 'topic', 'objective', 'competency')),
  CONSTRAINT `ck_curriculum_node__requirement` CHECK (`requirement` IN ('mandatory', 'optional', 'recommended', 'restricted'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CUR/config/public] Strand, theme, topic, learning objective or competency of a curriculum version';

CREATE TABLE `curriculum_version` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `curriculum_id` BINARY(16) NOT NULL,
  `version_label` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'e.g. 3.1',
  `base_version_id` BINARY(16) COMMENT 'Federal version a state adaptation layers on',
  `is_adaptation` BOOLEAN NOT NULL DEFAULT FALSE,
  `language` VARCHAR(35) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Curriculum versions by language of instruction',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `effective_from` DATE,
  `effective_to` DATE,
  `authored_by` BINARY(16) NOT NULL,
  `approved_by` BINARY(16),
  `approval_reason` TEXT,
  `source_document_id` BINARY(16) COMMENT 'Digitised source (captured from paper; human approval before publication)',
  `content_hash` BINARY(32) COMMENT 'Hash of the node tree at publication',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_curriculum_version_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_curriculum_version_curriculum_id_version_label` (`tenant_id`, `curriculum_id`, `version_label`),
  KEY `ix_curriculum_version_base_version_id` (`tenant_id`, `base_version_id`),
  KEY `ix_curriculum_version_authored_by` (`tenant_id`, `authored_by`),
  KEY `ix_curriculum_version_approved_by` (`tenant_id`, `approved_by`),
  CONSTRAINT `ck_curriculum_version__status` CHECK (`status` IN ('draft', 'review', 'approved', 'published', 'superseded', 'withdrawn')),
  CONSTRAINT `ck_curriculum_version__four_eyes` CHECK (approved_by IS NULL OR approved_by <> authored_by)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CUR/config/public] Immutable published version of a curriculum (copy-on-write; author ≠ approver)';

-- ============================================================================
-- Domain ASM — Assessment, grading, moderation, targets, report cards, examinations, results, GPA and transcripts
-- ============================================================================

CREATE TABLE `grade_band` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `grading_scale_id` BINARY(16) NOT NULL,
  `label` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'A1, B2, C4, Distinction, Level 3',
  `min_score` DECIMAL(7,3) NOT NULL,
  `max_score` DECIMAL(7,3) NOT NULL,
  `grade_points` DECIMAL(4,2),
  `is_pass` BOOLEAN NOT NULL,
  `is_credit` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Counts as a credit (5 credits incl. English and Mathematics)',
  `sort_order` SMALLINT NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_grade_band_grading_scale_id_label` (`tenant_id`, `grading_scale_id`, `label`),
  CONSTRAINT `ck_grade_band__range` CHECK (max_score >= min_score)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ASM/config/public] Band of a grading scale (contiguous and non-overlapping)';

CREATE TABLE `grading_scale` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `code` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `scale_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `version` INT UNSIGNED NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_grading_scale_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_grading_scale_scope_node_id_code_version` (`tenant_id`, `scope_node_id`, `code`, `version`),
  CONSTRAINT `ck_grading_scale__scale_kind` CHECK (`scale_kind` IN ('percentage', 'letter', 'grade_points', 'gpa', 'pass_fail', 'competency', 'degree_class')),
  CONSTRAINT `ck_grading_scale__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[ASM/config/public] Configurable grading scale (percentage, letter, grade points, GPA, pass/fail, competency levels, degree classes)';

-- ============================================================================
-- Domain CER — Certificate 360 and the state certificate registry — eligibility, issuance, signing, verification, reissue and anti-fraud
-- ============================================================================

CREATE TABLE `certificate` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `certificate_number` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '<country>-<authority>-<year>-<seq><check>; never reused (decision CD-08)',
  `verification_code` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Separate short code printed with the QR',
  `credential_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `learner_id` BINARY(16) COMMENT 'Holder (NULL only for approval certificates)',
  `institution_id` BINARY(16) NOT NULL,
  `qualification_id` BINARY(16),
  `programme_id` BINARY(16),
  `curriculum_version_id` BINARY(16),
  `award_date` DATE NOT NULL,
  `award_class` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Grade, division or classification',
  `holder_name_on_award` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'As printed',
  `eligibility_result_id` BINARY(16),
  `exception_id` BINARY(16) COMMENT 'Authorised exception recorded on the certificate',
  `template_id` BINARY(16) NOT NULL,
  `signatory_id` BINARY(16) NOT NULL,
  `payload` JSON NOT NULL COMMENT 'RFC 8785 canonical JSON payload that was signed',
  `payload_hash` BINARY(32) NOT NULL,
  `signature` VARBINARY(512) NOT NULL COMMENT 'ES256 signature',
  `signing_key_id` BINARY(16) NOT NULL,
  `vc_document` JSON COMMENT 'W3C Verifiable Credential 2.0 / Open Badges 3.0',
  `pdf_document_id` BINARY(16) COMMENT 'PDF/A with embedded signature (WORM bucket)',
  `supersedes_id` BINARY(16) COMMENT 'Original certificate superseded by this reissue/correction',
  `superseded_by` BINARY(16),
  `legacy_award_id` BINARY(16) COMMENT 'Digital copy bound to a legacy award',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `status_changed_at` DATETIME(6) NOT NULL,
  `award_key` VARCHAR(120) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (IF(`status` IN ('valid','suspended') AND `credential_kind` = 'certificate', CONCAT(HEX(`learner_id`), ':', HEX(`qualification_id`), ':', `award_date`), NULL)) STORED COMMENT 'One certificate per learner per qualification award while valid',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_certificate_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_certificate_certificate_number` (`tenant_id`, `certificate_number`),
  UNIQUE KEY `uq_certificate_verification_code` (`tenant_id`, `verification_code`),
  UNIQUE KEY `uq_certificate_payload_hash` (`tenant_id`, `payload_hash`),
  UNIQUE KEY `uq_certificate_award_key` (`tenant_id`, `award_key`),
  KEY `ix_certificate_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_certificate_learner_id` (`tenant_id`, `learner_id`),
  KEY `ix_certificate_institution_id_award_date` (`tenant_id`, `institution_id`, `award_date`),
  KEY `ix_certificate_qualification_id` (`tenant_id`, `qualification_id`),
  KEY `ix_certificate_programme_id` (`tenant_id`, `programme_id`),
  KEY `ix_certificate_curriculum_version_id` (`tenant_id`, `curriculum_version_id`),
  KEY `ix_certificate_eligibility_result_id` (`tenant_id`, `eligibility_result_id`),
  KEY `ix_certificate_exception_id` (`tenant_id`, `exception_id`),
  KEY `ix_certificate_template_id` (`tenant_id`, `template_id`),
  KEY `ix_certificate_signatory_id` (`tenant_id`, `signatory_id`),
  KEY `ix_certificate_signing_key_id` (`tenant_id`, `signing_key_id`),
  KEY `ix_certificate_supersedes_id` (`tenant_id`, `supersedes_id`),
  KEY `ix_certificate_superseded_by` (`tenant_id`, `superseded_by`),
  KEY `ix_certificate_legacy_award_id` (`tenant_id`, `legacy_award_id`),
  CONSTRAINT `ck_certificate__credential_kind` CHECK (`credential_kind` IN ('certificate', 'transcript', 'testimonial', 'approval_certificate', 'badge', 'micro_credential', 'certified_copy')),
  CONSTRAINT `ck_certificate__status` CHECK (`status` IN ('valid', 'suspended', 'revoked', 'superseded', 'corrected'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CER/master/confidential] Certificate 360 — authoritative award record (status valid, suspended, revoked, superseded, corrected)';

CREATE TABLE `certificate_delivery` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `certificate_id` BINARY(16) NOT NULL,
  `method` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `recipient_name` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `recipient_id_checked` VARCHAR(120) COLLATE utf8mb4_0900_ai_ci COMMENT 'Document type checked (no number stored)',
  `courier_tracking` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin,
  `delivered_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_certificate_delivery_certificate_id` (`tenant_id`, `certificate_id`),
  CONSTRAINT `ck_certificate_delivery__method` CHECK (`method` IN ('collection_in_person', 'tracked_courier', 'digital_only'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CER/event/confidential] Collection in person or tracked courier delivery of a printed certificate, with recipient identity';

CREATE TABLE `certificate_event` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `certificate_id` BINARY(16) NOT NULL,
  `event_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `reason` TEXT NOT NULL,
  `evidence_document_ids` JSON,
  `actor_user_id` BINARY(16) NOT NULL,
  `approver_user_id` BINARY(16) COMMENT 'Second approver for revocation and flagged cases',
  `workflow_instance_id` BINARY(16),
  `occurred_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_certificate_event_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_certificate_event_certificate_id` (`tenant_id`, `certificate_id`),
  KEY `ix_certificate_event_actor_user_id` (`tenant_id`, `actor_user_id`),
  KEY `ix_certificate_event_approver_user_id` (`tenant_id`, `approver_user_id`),
  KEY `ix_certificate_event_workflow_instance_id` (`tenant_id`, `workflow_instance_id`),
  CONSTRAINT `ck_certificate_event__event_kind` CHECK (`event_kind` IN ('issued', 'corrected', 'suspended', 'reinstated', 'revoked', 'reissued', 'superseded', 'certified_copy')),
  CONSTRAINT `ck_certificate_event__four_eyes` CHECK (approver_user_id IS NULL OR approver_user_id <> actor_user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CER/event/confidential] Certificate lifecycle event — issue, correct, suspend, reinstate, revoke, reissue, supersede (append-only)';

CREATE TABLE `certificate_template` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `credential_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `qualification_id` BINARY(16),
  `layout` JSON NOT NULL,
  `print_profile` JSON COMMENT 'Security paper features required',
  `version` INT UNSIGNED NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_certificate_template_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_certificate_template_scope_node_id_code_version` (`tenant_id`, `scope_node_id`, `code`, `version`),
  KEY `ix_certificate_template_qualification_id` (`tenant_id`, `qualification_id`),
  CONSTRAINT `ck_certificate_template__credential_kind` CHECK (`credential_kind` IN ('certificate', 'transcript', 'testimonial', 'approval_certificate', 'badge', 'micro_credential', 'certified_copy')),
  CONSTRAINT `ck_certificate_template__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CER/config/internal] Certificate template (layout, fields, security-print profile) per credential kind and issuer';

CREATE TABLE `eligibility_result` (
