  KEY `ix_eligibility_result_qualification_id` (`tenant_id`, `qualification_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CER/transaction/confidential] Eligibility-chain result for one learner (identity → institution → … → accreditation at award date → award approval)';

CREATE TABLE `eligibility_run` (
