  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_fee_schedule_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_fee_schedule_scope_node_id_service_variant_version` (`tenant_id`, `scope_node_id`, `service`, `variant`, `version`),
  CONSTRAINT `ck_fee_schedule__service` CHECK (`service` IN ('certificate_reissue', 'certified_copy', 'legacy_digital_copy', 'record_copy', 'transcript')),
  CONSTRAINT `ck_fee_schedule__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CER/config/public] State fee schedule for services (certificate reissue by type, reason and urgency; certified copies; record copies)';

CREATE TABLE `forgery_report` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `queried_number` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `certificate_id` BINARY(16),
  `reporter_org` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci,
  `reporter_contact` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci,
  `evidence_document_id` BINARY(16),
  `investigator_id` BINARY(16),
  `outcome` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_forgery_report_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_forgery_report_certificate_id` (`tenant_id`, `certificate_id`),
  KEY `ix_forgery_report_investigator_id` (`tenant_id`, `investigator_id`),
  CONSTRAINT `ck_forgery_report__outcome` CHECK (`outcome` IS NULL OR `outcome` IN ('no_issue', 'explained', 'action_taken', 'referred', 'confirmed')),
  CONSTRAINT `ck_forgery_report__status` CHECK (`status` IN ('open', 'in_progress', 'on_hold', 'closed', 'transferred'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CER/transaction/restricted] Suspected-forgery report from a verifier, with evidence image, routed to integrity investigators';

CREATE TABLE `identity_check` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `reissue_case_id` BINARY(16) NOT NULL,
  `method` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `outcome` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'A mismatch routes to manual review, never auto-rejects',
  `consent_captured` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Explicit consent for facial match; template discarded after the check',
  `detail` JSON,
  `checked_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_identity_check_reissue_case_id` (`tenant_id`, `reissue_case_id`),
  CONSTRAINT `ck_identity_check__method` CHECK (`method` IN ('nin_check', 'otp', 'facial_match', 'document_review', 'manual_review')),
  CONSTRAINT `ck_identity_check__outcome` CHECK (`outcome` IN ('match', 'partial_match', 'no_match', 'manual_review', 'error'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CER/event/restricted] Identity-verification step for a reissue or record-request case (NIN, OTP, facial match with liveness, manual review)';

CREATE TABLE `legacy_award` (
