  `award_year` SMALLINT NOT NULL,
  `original_number` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin,
  `source_document_id` BINARY(16) NOT NULL COMMENT 'Digitised register, broadsheet or counterfoil page',
  `verified_by` BINARY(16) NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
