  KEY `ix_legacy_award_verified_by` (`tenant_id`, `verified_by`),
  CONSTRAINT `ck_legacy_award__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CER/master/confidential] Legacy award record created from the digitised archive (marked "Verified from archive" with source pages)';

CREATE TABLE `print_job` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `certificate_id` BINARY(16) NOT NULL,
  `stock_id` BINARY(16) NOT NULL,
  `printer_ref` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `printed_by` BINARY(16) NOT NULL,
  `outcome` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `printed_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_print_job_certificate_id` (`tenant_id`, `certificate_id`),
  KEY `ix_print_job_stock_id` (`tenant_id`, `stock_id`),
  KEY `ix_print_job_printed_by` (`tenant_id`, `printed_by`),
  CONSTRAINT `ck_print_job__outcome` CHECK (`outcome` IN ('printed', 'spoiled', 'refused'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CER/event/restricted] Print of a signed, approved certificate on registered stock by an authorised printer';

CREATE TABLE `registry_publication` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `certificate_event_id` BINARY(16) NOT NULL,
  `target` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `attempts` SMALLINT NOT NULL DEFAULT 0,
  `published_at` DATETIME(6),
  `last_error` VARCHAR(1000) COLLATE utf8mb4_0900_ai_ci,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_registry_publication_certificate_event_id_target` (`tenant_id`, `certificate_event_id`, `target`),
  CONSTRAINT `ck_registry_publication__target` CHECK (`target` IN ('state_registry', 'state_portal', 'national_service', 'education_passport')),
  CONSTRAINT `ck_registry_publication__status` CHECK (`status` IN ('queued', 'sent', 'delivered', 'read', 'failed', 'retrying', 'abandoned', 'processed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CER/queue/internal] Publication of a certificate event to the state registry and linked platforms (≤ 60 s) and the Education Passport';

CREATE TABLE `reissue_case` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `case_number` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `certificate_id` BINARY(16) COMMENT 'Located award (or legacy_award_id)',
  `legacy_award_id` BINARY(16),
  `applicant_user_id` BINARY(16),
  `applicant_name` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `applicant_phone` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `reason` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `urgency` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'standard',
  `evidence_document_ids` JSON NOT NULL,
  `fee_schedule_id` BINARY(16),
  `amount_due_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `payment_reference` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Remita RRR',
  `paid_at` DATETIME(6) COMMENT 'No payment, no processing',
  `waiver_approved_by` BINARY(16) COMMENT 'Audited waiver (e.g. issuer error)',
  `integrity_flag` BOOLEAN NOT NULL DEFAULT FALSE,
  `reviewer_id` BINARY(16),
  `second_approver_id` BINARY(16),
  `new_certificate_id` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_reissue_case_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_reissue_case_case_number` (`tenant_id`, `case_number`),
  KEY `ix_reissue_case_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_reissue_case_certificate_id` (`tenant_id`, `certificate_id`),
  KEY `ix_reissue_case_legacy_award_id` (`tenant_id`, `legacy_award_id`),
  KEY `ix_reissue_case_applicant_user_id` (`tenant_id`, `applicant_user_id`),
  KEY `ix_reissue_case_fee_schedule_id` (`tenant_id`, `fee_schedule_id`),
  KEY `ix_reissue_case_waiver_approved_by` (`tenant_id`, `waiver_approved_by`),
  KEY `ix_reissue_case_reviewer_id` (`tenant_id`, `reviewer_id`),
  KEY `ix_reissue_case_second_approver_id` (`tenant_id`, `second_approver_id`),
  KEY `ix_reissue_case_new_certificate_id` (`tenant_id`, `new_certificate_id`),
  CONSTRAINT `ck_reissue_case__reason` CHECK (`reason` IN ('lost_or_stolen', 'damaged', 'change_of_name', 'issuer_error', 'certified_copy', 'legacy_digital_copy')),
  CONSTRAINT `ck_reissue_case__urgency` CHECK (`urgency` IN ('standard', 'express')),
  CONSTRAINT `ck_reissue_case__status` CHECK (`status` IN ('submitted', 'identity_check', 'archive_search', 'awaiting_payment', 'in_review', 'approved', 'issued', 'delivered', 'rejected', 'withdrawn')),
  CONSTRAINT `ck_reissue_case__four_eyes` CHECK (second_approver_id IS NULL OR reviewer_id IS NULL OR second_approver_id <> reviewer_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CER/transaction/restricted] Certificate reissue, correction, certified copy or legacy digital copy request';

CREATE TABLE `security_stock` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `serial` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `batch_ref` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `holder_institution_id` BINARY(16),
  `certificate_id` BINARY(16) COMMENT 'Certificate printed on this sheet',
  `state` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `state_changed_at` DATETIME(6) NOT NULL,
  `destruction_witness` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_security_stock_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_security_stock_serial` (`tenant_id`, `serial`),
  KEY `ix_security_stock_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_security_stock_holder_institution_id` (`tenant_id`, `holder_institution_id`),
  KEY `ix_security_stock_certificate_id` (`tenant_id`, `certificate_id`),
  CONSTRAINT `ck_security_stock__state` CHECK (`state` IN ('received', 'issued_to_institution', 'printed', 'spoiled', 'destroyed', 'lost'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CER/master/restricted] Security paper sheet by serial (received → issued to institution → printed / spoiled / destroyed)';

CREATE TABLE `signatory` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `user_id` BINARY(16) NOT NULL,
  `title_on_award` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `signature_image_document_id` BINARY(16),
  `max_batch_without_second` INT UNSIGNED COMMENT 'Four-eyes threshold for batches',
  `valid_from` DATE NOT NULL COMMENT 'Effective from (inclusive) — history: effective',
  `valid_to` DATE COMMENT 'Effective to (inclusive); NULL = open-ended — history: effective',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_signatory_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_signatory_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_signatory_user_id` (`tenant_id`, `user_id`),
  CONSTRAINT `ck_signatory__valid` CHECK (valid_to IS NULL OR valid_to >= valid_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CER/master/internal] Authorised signatory of an issuing authority (with specimen and authority period)';

CREATE TABLE `signing_key` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `kid` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'e.g. abia-moe-2026-01',
  `algorithm` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'ES256',
  `public_jwk` JSON NOT NULL,
  `hsm_key_ref` VARCHAR(255) COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Key handle in the HSM/KMS',
  `ceremony_document_id` BINARY(16) COMMENT 'Key ceremony record with ministry witnesses',
  `activated_at` DATETIME(6) NOT NULL,
  `retired_at` DATETIME(6) COMMENT 'Retired keys still verify old signatures',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_signing_key_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_signing_key_kid` (`tenant_id`, `kid`),
  KEY `ix_signing_key_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_signing_key__status` CHECK (`status` IN ('pending', 'active', 'retired', 'compromised'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CER/config/public] Metadata of an HSM-held issuing key (the private key never leaves the HSM; public keys at the JWKS endpoint)';

CREATE TABLE `verification` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `certificate_id` BINARY(16) COMMENT 'NULL when no match',
  `queried_number` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `channel` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `api_client_id` BINARY(16) COMMENT 'Bulk verifiers',
  `result` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `ip_hash` BINARY(32) COMMENT 'Keyed hash of the client IP (abuse detection without storing the IP)',
  `verified_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`, `verified_at`),
  KEY `ix_verification_queried_number_verified_at` (`tenant_id`, `queried_number`, `verified_at`),
  KEY `ix_verification_certificate_id` (`tenant_id`, `certificate_id`),
  CONSTRAINT `ck_verification__channel` CHECK (`channel` IN ('web_number', 'qr', 'secure_link', 'bulk_api', 'passport_share')),
  CONSTRAINT `ck_verification__result` CHECK (`result` IN ('valid', 'superseded', 'revoked', 'corrected', 'suspended', 'not_found', 'rate_limited'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[CER/event/internal] Public or API certificate verification (minimum disclosure, rate-limited, visible to the holder)'
PARTITION BY RANGE COLUMNS (`verified_at`) (
  PARTITION p202609 VALUES LESS THAN ('2026-10-01 00:00:00'),
  PARTITION p202610 VALUES LESS THAN ('2026-11-01 00:00:00'),
  PARTITION p202611 VALUES LESS THAN ('2026-12-01 00:00:00'),
  PARTITION p202612 VALUES LESS THAN ('2027-01-01 00:00:00'),
  PARTITION p202701 VALUES LESS THAN ('2027-02-01 00:00:00'),
  PARTITION p202702 VALUES LESS THAN ('2027-03-01 00:00:00'),
  PARTITION p202703 VALUES LESS THAN ('2027-04-01 00:00:00'),
  PARTITION p202704 VALUES LESS THAN ('2027-05-01 00:00:00'),
  PARTITION p202705 VALUES LESS THAN ('2027-06-01 00:00:00'),
  PARTITION p202706 VALUES LESS THAN ('2027-07-01 00:00:00'),
  PARTITION p202707 VALUES LESS THAN ('2027-08-01 00:00:00'),
  PARTITION p202708 VALUES LESS THAN ('2027-09-01 00:00:00'),
  PARTITION pmax VALUES LESS THAN (MAXVALUE)
);

