  `resolution` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `explanation` VARCHAR(1000) COLLATE utf8mb4_0900_ai_ci,
  `resolved_by` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_census_flag_snapshot_id` (`tenant_id`, `snapshot_id`),
  KEY `ix_census_flag_learner_id` (`tenant_id`, `learner_id`),
  KEY `ix_census_flag_resolved_by` (`tenant_id`, `resolved_by`),
  CONSTRAINT `ck_census_flag__flag_kind` CHECK (`flag_kind` IN ('no_attendance_since_start', 'identity_conflict', 'unexplained_rise')),
  CONSTRAINT `ck_census_flag__resolution` CHECK (`resolution` IS NULL OR `resolution` IN ('cleared', 'explained', 'removed_from_count')),
  CONSTRAINT `ck_census_flag__status` CHECK (`status` IN ('open', 'in_progress', 'resolved', 'dismissed', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[SUB/queue/confidential] Ghost-learner flag before freezing (no attendance since period start, identity conflict, unexplained rise) — cleared or explained by the head';

CREATE TABLE `census_learner` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `snapshot_id` BINARY(16) NOT NULL,
  `learner_id` BINARY(16) NOT NULL,
  `enrolment_id` BINARY(16) NOT NULL,
  `inclusion` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `reason` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_census_learner_snapshot_id_learner_id` (`tenant_id`, `snapshot_id`, `learner_id`),
  KEY `ix_census_learner_learner_id` (`tenant_id`, `learner_id`),
  KEY `ix_census_learner_enrolment_id` (`tenant_id`, `enrolment_id`),
  CONSTRAINT `ck_census_learner__inclusion` CHECK (`inclusion` IN ('billable', 'excluded', 'exempt')),
  CONSTRAINT `ck_census_learner__reason` CHECK (`reason` IS NULL OR `reason` IN ('withdrawn_before_census', 'duplicate', 'unverified', 'other_institution_holds', 'exempt'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[SUB/snapshot/confidential] Learner included or excluded in a census snapshot, with reason (append-only)';

CREATE TABLE `census_snapshot` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `billing_period_id` BINARY(16) NOT NULL,
  `version` INT UNSIGNED NOT NULL,
  `enrolled` INT UNSIGNED NOT NULL,
  `verified` INT UNSIGNED NOT NULL,
  `excluded` INT UNSIGNED NOT NULL,
  `exempted` INT UNSIGNED NOT NULL,
  `billable` INT UNSIGNED NOT NULL,
  `open_flags` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Count cannot be frozen while flags are open',
  `confirmed_by` BINARY(16),
  `confirmed_at` DATETIME(6),
  `frozen_at` DATETIME(6),
  `content_hash` BINARY(32),
  `challenge` JSON COMMENT 'Evidence-based challenge and decision',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_census_snapshot_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_census_snapshot_institution_id_billing_period_id_version` (`tenant_id`, `institution_id`, `billing_period_id`, `version`),
  KEY `ix_census_snapshot_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_census_snapshot_billing_period_id` (`tenant_id`, `billing_period_id`),
  KEY `ix_census_snapshot_confirmed_by` (`tenant_id`, `confirmed_by`),
  CONSTRAINT `ck_census_snapshot__status` CHECK (`status` IN ('draft', 'flags_open', 'awaiting_confirmation', 'confirmed', 'challenged', 'frozen', 'superseded')),
  CONSTRAINT `ck_census_snapshot__frozen_needs_clear` CHECK (status <> 'frozen' OR (open_flags = 0 AND content_hash IS NOT NULL AND confirmed_by IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[SUB/snapshot/confidential] Billable-learner count of an institution for a period (flags cleared, head-confirmed, frozen and hashed; amendments versioned)';

CREATE TABLE `reconciliation_line` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `statement_id` BINARY(16) NOT NULL,
  `institution_id` BINARY(16) NOT NULL,
  `billed_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `exempted_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `collected_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `remitted_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `dispute` JSON COMMENT 'Dispute logged against the line',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_reconciliation_line_statement_id_institution_id` (`tenant_id`, `statement_id`, `institution_id`),
  KEY `ix_reconciliation_line_institution_id` (`tenant_id`, `institution_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[SUB/snapshot/confidential] Line of a reconciliation statement by institution (with logged disputes)';

CREATE TABLE `reconciliation_statement` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `billing_period_id` BINARY(16) NOT NULL,
  `billed_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `exempted_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `collected_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `remitted_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `outstanding_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `late_remittance_charge_minor` BIGINT NOT NULL DEFAULT 0 COMMENT '(minor units)',
  `service_credits_minor` BIGINT NOT NULL DEFAULT 0 COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `state_signed_by` BINARY(16),
  `state_signed_at` DATETIME(6),
  `operator_signed_by` BINARY(16),
  `operator_signed_at` DATETIME(6),
  `content_hash` BINARY(32),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_reconciliation_statement_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_reconciliation_statement_billing_period_id` (`tenant_id`, `billing_period_id`),
  KEY `ix_reconciliation_statement_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_reconciliation_statement_state_signed_by` (`tenant_id`, `state_signed_by`),
  KEY `ix_reconciliation_statement_operator_signed_by` (`tenant_id`, `operator_signed_by`),
  CONSTRAINT `ck_reconciliation_statement__status` CHECK (`status` IN ('draft', 'in_review', 'state_signed', 'operator_signed', 'signed_locked', 'disputed')),
  CONSTRAINT `ck_reconciliation_statement__dual_signature` CHECK (operator_signed_by IS NULL OR state_signed_by IS NULL OR operator_signed_by <> state_signed_by)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[SUB/snapshot/confidential] Period statement — billed, exempted, collected, remitted, outstanding — with dual sign-off (state + SDIN), locked and hashed';

CREATE TABLE `remittance` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `billing_period_id` BINARY(16) NOT NULL,
  `advice_ref` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `bank_ref` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `amount_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `remitted_on` DATE NOT NULL,
  `recorded_by` BINARY(16) NOT NULL,
  `approved_by` BINARY(16) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_remittance_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_remittance_advice_ref` (`tenant_id`, `advice_ref`),
  KEY `ix_remittance_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_remittance_billing_period_id` (`tenant_id`, `billing_period_id`),
  KEY `ix_remittance_recorded_by` (`tenant_id`, `recorded_by`),
  KEY `ix_remittance_approved_by` (`tenant_id`, `approved_by`),
  CONSTRAINT `ck_remittance__amount_min` CHECK (`amount_minor` >= 0),
  CONSTRAINT `ck_remittance__dual_control` CHECK (approved_by <> recorded_by)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[SUB/event/confidential] Remittance of collected SDAF from the State Government to SDIN, with advice (recorder ≠ approver; append-only)';

CREATE TABLE `remittance_allocation` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `remittance_id` BINARY(16) NOT NULL,
  `collection_id` BINARY(16) NOT NULL,
  `amount_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_remittance_allocation_remittance_id_collection_id` (`tenant_id`, `remittance_id`, `collection_id`),
  KEY `ix_remittance_allocation_collection_id` (`tenant_id`, `collection_id`),
  CONSTRAINT `ck_remittance_allocation__amount_min` CHECK (`amount_minor` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[SUB/link/confidential] Allocation of a remittance to the collections it covers';

CREATE TABLE `sdaf_collection` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `demand_id` BINARY(16) NOT NULL,
  `state_receipt_ref` VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'State e-receipt / collection-system id — idempotency key',
  `channel` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `amount_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `paid_at` DATETIME(6) NOT NULL,
  `statement_matched_at` DATETIME(6) COMMENT 'Daily reconciliation against the state collection-account statement',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sdaf_collection_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_sdaf_collection_state_receipt_ref` (`tenant_id`, `state_receipt_ref`),
  KEY `ix_sdaf_collection_demand_id` (`tenant_id`, `demand_id`),
  CONSTRAINT `ck_sdaf_collection__channel` CHECK (`channel` IN ('state_portal', 'remita', 'bank_branch', 'pos', 'ussd', 'bank_transfer')),
  CONSTRAINT `ck_sdaf_collection__amount_min` CHECK (`amount_minor` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[SUB/event/confidential] Payment into the state revenue account against a demand (posted idempotently from state notifications; append-only)';

CREATE TABLE `sdaf_demand` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `demand_number` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `institution_id` BINARY(16) NOT NULL,
  `billing_period_id` BINARY(16) NOT NULL,
  `snapshot_id` BINARY(16) NOT NULL,
  `payer_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `payer_ref` BINARY(16) COMMENT 'Government payer, guardian, learner or sponsor',
  `learner_id` BINARY(16) COMMENT 'Individual assessments only',
  `billable_count` INT UNSIGNED NOT NULL,
  `waived_count` INT UNSIGNED NOT NULL,
  `rate_id` BINARY(16) NOT NULL,
  `amount_minor` BIGINT NOT NULL COMMENT '(billable − waived) × rate (minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `revenue_code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `payment_reference` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Remita RRR or state e-revenue reference',
  `issued_at` DATETIME(6) NOT NULL,
  `is_basic_education` BOOLEAN NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sdaf_demand_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_sdaf_demand_demand_number` (`tenant_id`, `demand_number`),
  UNIQUE KEY `uq_sdaf_demand_payment_reference` (`tenant_id`, `payment_reference`),
  KEY `ix_sdaf_demand_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_sdaf_demand_institution_id` (`tenant_id`, `institution_id`),
  KEY `ix_sdaf_demand_billing_period_id` (`tenant_id`, `billing_period_id`),
  KEY `ix_sdaf_demand_snapshot_id` (`tenant_id`, `snapshot_id`),
  KEY `ix_sdaf_demand_learner_id` (`tenant_id`, `learner_id`),
  KEY `ix_sdaf_demand_rate_id` (`tenant_id`, `rate_id`),
  CONSTRAINT `ck_sdaf_demand__payer_kind` CHECK (`payer_kind` IN ('government', 'parent_or_student', 'sponsor', 'scholarship', 'split')),
  CONSTRAINT `ck_sdaf_demand__amount_min` CHECK (`amount_minor` >= 0),
  CONSTRAINT `ck_sdaf_demand__status` CHECK (`status` IN ('issued', 'part_paid', 'paid', 'overdue', 'cancelled')),
  CONSTRAINT `ck_sdaf_demand__ube_act` CHECK (NOT (is_basic_education AND payer_kind <> 'government'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[SUB/transaction/confidential] SDAF demand notice (consolidated to a government payer) or individual assessment (never at basic-education level)';

CREATE TABLE `sdaf_exemption` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `learner_id` BINARY(16) NOT NULL,
  `billing_period_id` BINARY(16) NOT NULL,
  `category_id` BINARY(16) NOT NULL,
  `evidence_document_id` BINARY(16) NOT NULL,
  `requested_by` BINARY(16) NOT NULL,
  `approved_by` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sdaf_exemption_learner_id_billing_period_id` (`tenant_id`, `learner_id`, `billing_period_id`),
  KEY `ix_sdaf_exemption_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_sdaf_exemption_billing_period_id` (`tenant_id`, `billing_period_id`),
  KEY `ix_sdaf_exemption_category_id` (`tenant_id`, `category_id`),
  KEY `ix_sdaf_exemption_requested_by` (`tenant_id`, `requested_by`),
  KEY `ix_sdaf_exemption_approved_by` (`tenant_id`, `approved_by`),
  CONSTRAINT `ck_sdaf_exemption__status` CHECK (`status` IN ('draft', 'submitted', 'in_review', 'approved', 'rejected', 'cancelled', 'fulfilled')),
  CONSTRAINT `ck_sdaf_exemption__four_eyes` CHECK (approved_by IS NULL OR approved_by <> requested_by)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[SUB/transaction/restricted] Approved SDAF exemption for a learner and period (learner stays in the headcount; reported separately)';

CREATE TABLE `sdaf_exemption_category` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `code` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `funding_rule` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `evidence_required` VARCHAR(500) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `version` INT UNSIGNED NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sdaf_exemption_category_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_sdaf_exemption_category_scope_node_id_code_version` (`tenant_id`, `scope_node_id`, `code`, `version`),
  CONSTRAINT `ck_sdaf_exemption_category__funding_rule` CHECK (`funding_rule` IN ('borne_by_state', 'waived')),
  CONSTRAINT `ck_sdaf_exemption_category__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[SUB/config/internal] Exemption category (SEND, orphans and vulnerable children, IDPs, scholarship holders) with funding rule';

CREATE TABLE `sdaf_payer_rule` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_type` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `education_level` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `is_basic_education` BOOLEAN NOT NULL COMMENT 'Public primary or junior secondary',
  `payer` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `split` JSON COMMENT 'Shares when payer = split',
  `version` INT UNSIGNED NOT NULL,
