  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sdaf_payer_rule_scope_node_id_institution_type_educa_c05f6d68` (`tenant_id`, `scope_node_id`, `institution_type`, `education_level`, `version`),
  CONSTRAINT `ck_sdaf_payer_rule__payer` CHECK (`payer` IN ('government', 'parent_or_student', 'sponsor', 'scholarship', 'split')),
  CONSTRAINT `ck_sdaf_payer_rule__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn')),
  CONSTRAINT `ck_sdaf_payer_rule__ube_act` CHECK (NOT (is_basic_education AND payer <> 'government'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[SUB/config/internal] Who pays the SDAF for an institution type and level (government only for public primary and JSS)';

