) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[SUB/config/internal] Version of the state-approved SDAF rate card (propose → approve → publish)';

CREATE TABLE `unmatched_collection` (
