) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[SUB/queue/confidential] State collection notification not matched to a demand, or a held duplicate';

-- ============================================================================
-- Domain INT — Intelligence and automation — alerts, investigations, improvement, recommendations, early warning, model register, agents, assistant and planning
-- ============================================================================

CREATE TABLE `agent` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `template_code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `template_version` INT UNSIGNED NOT NULL,
  `service_identity_id` BINARY(16) NOT NULL COMMENT 'Registry service identity',
  `owner_user_id` BINARY(16) NOT NULL,
  `level` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `state_max_level` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Institutions may only lower',
  `triggers` JSON NOT NULL,
  `limits` JSON NOT NULL COMMENT 'Messages, cost, records touched per day',
  `sandbox_result` JSON COMMENT 'Simulation against last month''s data',
  `approved_by` BINARY(16),
  `head_approved_by` BINARY(16) COMMENT 'Required for A2 and above',
  `next_reapproval_on` DATE COMMENT 'Quarterly',
  `error_rate` DECIMAL(7,6),
  `paused_at` DATETIME(6),
  `paused_by` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_agent_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_agent__level` CHECK (`level` IN ('a0', 'a1', 'a2', 'a3')),
  CONSTRAINT `ck_agent__state_max_level` CHECK (`state_max_level` IN ('a0', 'a1', 'a2', 'a3')),
  CONSTRAINT `ck_agent__status` CHECK (`status` IN ('draft', 'sandbox', 'awaiting_approval', 'active', 'paused', 'level_lowered', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INT/config/internal] Configured automation agent (owner, service identity, level, scope, limits, approval, status)';

CREATE TABLE `agent_action` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `agent_id` BINARY(16) NOT NULL,
  `owner_user_id` BINARY(16) NOT NULL,
  `trigger_detail` JSON NOT NULL,
  `evidence` JSON NOT NULL,
  `rule_applied` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci,
  `tool` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `parameters` JSON NOT NULL COMMENT 'Typed, validated parameters (retrieved text is never executed)',
  `level` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `outcome` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `explanation` TEXT NOT NULL,
  `undo_until` DATETIME(6) COMMENT '24-hour undo for reversible A2 actions',
  `undone_action_id` BINARY(16) COMMENT 'Undo record for a previous action',
  `occurred_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`, `occurred_at`),
  KEY `ix_agent_action_tenant` (`tenant_id`),
  CONSTRAINT `ck_agent_action__level` CHECK (`level` IN ('a0', 'a1', 'a2', 'a3')),
  CONSTRAINT `ck_agent_action__outcome` CHECK (`outcome` IN ('proposed', 'executed', 'held_paused', 'refused_policy', 'failed', 'undone'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INT/event/internal] Action taken or proposed by an agent — trigger, evidence, rule, tool call, outcome, owner ("Agent X for Owner Y"); append-only'
PARTITION BY RANGE COLUMNS (`occurred_at`) (
  PARTITION p202609 VALUES LESS THAN ('2026-10-01 00:00:00'),
