  PARTITION p202701 VALUES LESS THAN ('2027-02-01 00:00:00'),
  PARTITION p202702 VALUES LESS THAN ('2027-03-01 00:00:00'),
  PARTITION p202703 VALUES LESS THAN ('2027-04-01 00:00:00'),
  PARTITION p202704 VALUES LESS THAN ('2027-05-01 00:00:00'),
  PARTITION p202705 VALUES LESS THAN ('2027-06-01 00:00:00'),
  PARTITION p202706 VALUES LESS THAN ('2027-07-01 00:00:00'),
  PARTITION p202707 VALUES LESS THAN ('2027-08-01 00:00:00'),
  PARTITION p202708 VALUES LESS THAN ('2027-09-01 00:00:00'),
  PARTITION pmax VALUES LESS THAN (MAXVALUE)
);

CREATE TABLE `alert` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `rule_key` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `severity` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `priority` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `what_changed` TEXT NOT NULL,
  `why_it_matters` TEXT NOT NULL,
  `evidence` JSON NOT NULL,
  `recommended_action` TEXT,
  `subject_kind` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `subject_id` BINARY(16) NOT NULL,
  `owner_role` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `owner_user_id` BINARY(16),
  `due_at` DATETIME(6) NOT NULL,
  `dedupe_key` VARCHAR(160) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'rule:subject while open',
  `escalation_level` SMALLINT NOT NULL DEFAULT 0,
  `snoozed_until` DATETIME(6),
  `investigation_id` BINARY(16),
  `resolved_at` DATETIME(6),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_alert_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_alert_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_alert_dedupe_key_status` (`tenant_id`, `dedupe_key`, `status`),
  KEY `ix_alert_owner_user_id_status` (`tenant_id`, `owner_user_id`, `status`),
  KEY `ix_alert_due_at` (`tenant_id`, `due_at`),
  KEY `ix_alert_investigation_id` (`tenant_id`, `investigation_id`),
  CONSTRAINT `ck_alert__severity` CHECK (`severity` IN ('critical', 'high', 'moderate', 'info')),
  CONSTRAINT `ck_alert__priority` CHECK (`priority` IN ('p1', 'p2', 'p3', 'information')),
  CONSTRAINT `ck_alert__status` CHECK (`status` IN ('open', 'acknowledged', 'in_progress', 'snoozed', 'escalated', 'resolved', 'dismissed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INT/transaction/internal] Alert instance (what changed, why it matters, evidence, severity, recommended action, owner, due date) — deduplicated and escalated';

CREATE TABLE `alert_event` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `alert_id` BINARY(16) NOT NULL,
  `event_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `actor` BINARY(16),
  `note` VARCHAR(1000) COLLATE utf8mb4_0900_ai_ci,
  `occurred_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  KEY `ix_alert_event_alert_id` (`tenant_id`, `alert_id`),
  CONSTRAINT `ck_alert_event__event_kind` CHECK (`event_kind` IN ('raised', 'acknowledged', 'assigned', 'escalated', 'snoozed', 'commented', 'resolved', 'reopened'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INT/event/internal] History of an alert (raised, acknowledged, escalated, snoozed, resolved) — append-only';

CREATE TABLE `alert_rule` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
