  `severity` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `owner_role` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `due_days` SMALLINT NOT NULL,
  `escalation` JSON NOT NULL,
  `version` INT UNSIGNED NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_alert_rule_scope_node_id_rule_key_version` (`tenant_id`, `scope_node_id`, `rule_key`, `version`),
  KEY `ix_alert_rule_policy_rule_id` (`tenant_id`, `policy_rule_id`),
  CONSTRAINT `ck_alert_rule__severity` CHECK (`severity` IN ('critical', 'high', 'moderate', 'info')),
  CONSTRAINT `ck_alert_rule__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INT/config/internal] Alert rule (indicator, threshold, severity, owner role, due, escalation chain) — policy-engine backed';

CREATE TABLE `investigation` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `stage` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `problem` TEXT NOT NULL,
  `evidence` JSON,
  `root_cause` TEXT,
  `intervention_ref` BINARY(16) COMMENT 'Intervention or corrective action',
  `responsible_user_id` BINARY(16) COMMENT 'Required before advancing to outcome',
  `due_on` DATE,
  `outcome` TEXT,
  `owner_user_id` BINARY(16) NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_investigation_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_investigation_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_investigation__stage` CHECK (`stage` IN ('problem', 'evidence', 'root_cause', 'intervention', 'responsible_person', 'outcome')),
  CONSTRAINT `ck_investigation__status` CHECK (`status` IN ('open', 'in_progress', 'on_hold', 'closed', 'transferred')),
  CONSTRAINT `ck_investigation__responsible_before_outcome` CHECK (stage <> 'outcome' OR (responsible_user_id IS NOT NULL AND due_on IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INT/transaction/confidential] Follow-the-Problem investigation (Problem → Evidence → Root cause → Intervention → Responsible person → Outcome)';

CREATE TABLE `model_deployment` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
