  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_model_deployment_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_model_deployment_approved_by` (`tenant_id`, `approved_by`),
  CONSTRAINT `ck_model_deployment__valid` CHECK (valid_to IS NULL OR valid_to >= valid_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INT/config/internal] Approval of a model version for use in a state (state DPO and ministry sign-off)';

