-- ============================================================================
-- Domain RPT — Reporting, semantic layer registry, government returns, scheduled reports and lineage
-- ============================================================================

CREATE TABLE `metric_definition` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `metric_code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'e.g. ATT-RATE, CUR-COVERAGE',
  `name` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `definition` JSON NOT NULL COMMENT 'From metrics.yaml at the published CEDA version',
  `target` DECIMAL(12,4),
  `direction` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `label_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'verified, calculated, estimated',
  `is_equity_indicator` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Shown only where jurisdiction policy allows',
  `ceda_version` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `version` INT UNSIGNED NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_metric_definition_scope_node_id_metric_code_version` (`tenant_id`, `scope_node_id`, `metric_code`, `version`),
  CONSTRAINT `ck_metric_definition__direction` CHECK (`direction` IN ('higher_is_better', 'lower_is_better', 'target_band')),
  CONSTRAINT `ck_metric_definition__label_kind` CHECK (`label_kind` IN ('verified', 'calculated', 'estimated')),
  CONSTRAINT `ck_metric_definition__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[RPT/config/public] Published semantic-layer metric (definition, formula, grain, source, owner, refresh, target, suppression)';

CREATE TABLE `report_definition` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
