  `owner_user_id` BINARY(16),
  `version` INT UNSIGNED NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_report_definition_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_report_definition_scope_node_id_code_version` (`tenant_id`, `scope_node_id`, `code`, `version`),
  KEY `ix_report_definition_owner_user_id` (`tenant_id`, `owner_user_id`),
  CONSTRAINT `ck_report_definition__report_kind` CHECK (`report_kind` IN ('standard', 'statutory', 'saved_query', 'board_report', 'inspection_pack')),
  CONSTRAINT `ck_report_definition__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[RPT/config/internal] Report in the library (standard, statutory or saved builder query) with permission trimming and suppression';

CREATE TABLE `report_schedule` (
