) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[RPT/config/internal] Statutory return definition (UBEC census, capitation, exam-body, regulator exports) with validation rules';

CREATE TABLE `return_submission` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
