  `client_id` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `secret_hash` BINARY(32) COMMENT 'Client secret hash (or mTLS certificate thumbprint)',
  `certificate_thumbprint` BINARY(32),
  `scopes` JSON NOT NULL,
  `agreement_id` BINARY(16),
  `rate_limit_per_minute` INT UNSIGNED NOT NULL,
  `service_identity_id` BINARY(16) NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_api_client_client_id` (`tenant_id`, `client_id`),
  KEY `ix_api_client_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_api_client_agreement_id` (`tenant_id`, `agreement_id`),
  KEY `ix_api_client_service_identity_id` (`tenant_id`, `service_identity_id`),
  CONSTRAINT `ck_api_client__client_kind` CHECK (`client_kind` IN ('partner', 'bulk_verifier', 'government_system', 'lms', 'mobile_app', 'internal_service')),
  CONSTRAINT `ck_api_client__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INTG/config/internal] API client (partner, verifier, government system, LMS) with OAuth scopes, mTLS binding and rate limits';

CREATE TABLE `data_sharing_agreement` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
