  CONSTRAINT `ck_data_sharing_agreement__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INTG/config/internal] Data-sharing agreement (purpose, datasets, legal basis, parties, residency, expiry)';

CREATE TABLE `exchange_transfer` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `agreement_id` BINARY(16) NOT NULL,
  `direction` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `dataset` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `subject_ref` BINARY(16) COMMENT 'Learner or institution',
  `payload_hash` BINARY(32) NOT NULL,
  `payload_format` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'OneRoster 1.2, Ed-Fi style, PESC transcript …',
  `counterpart_ref` VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin,
  `occurred_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
