  KEY `ix_exchange_transfer_agreement_id` (`tenant_id`, `agreement_id`),
  CONSTRAINT `ck_exchange_transfer__direction` CHECK (`direction` IN ('outbound', 'inbound')),
  CONSTRAINT `ck_exchange_transfer__dataset` CHECK (`dataset` IN ('learner_record', 'transcript', 'results', 'institution', 'staff', 'funding', 'attendance', 'outcomes'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INTG/event/confidential] Global Education Data Exchange transfer (learner records, transcripts, results, institution, funding, attendance, outcomes)';

CREATE TABLE `idempotency_key` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `principal_id` BINARY(16) NOT NULL,
  `idem_key` VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `request_hash` BINARY(32) NOT NULL,
  `response_status` SMALLINT NOT NULL,
  `response_body` JSON,
  `expires_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_idempotency_key_principal_id_idem_key` (`tenant_id`, `principal_id`, `idem_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INTG/queue/internal] Client Idempotency-Key and the stored response (retained 24 hours; offline sync operations use the same table)';

CREATE TABLE `import_job` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `template` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source_document_id` BINARY(16) NOT NULL,
  `mapping` JSON NOT NULL,
  `rows_total` INT UNSIGNED NOT NULL,
  `rows_valid` INT UNSIGNED NOT NULL,
  `rows_matched` INT UNSIGNED NOT NULL,
  `rows_committed` INT UNSIGNED NOT NULL,
  `committed_at` DATETIME(6),
  `rollback_until` DATETIME(6),
  `rolled_back_at` DATETIME(6),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_import_job_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_import_job_scope` (`tenant_id`, `scope_node_id`),
  CONSTRAINT `ck_import_job__template` CHECK (`template` IN ('learners', 'guardians', 'staff', 'classes', 'enrolments', 'marks', 'balances', 'assessments', 'curriculum')),
  CONSTRAINT `ck_import_job__status` CHECK (`status` IN ('uploaded', 'mapped', 'validating', 'validated', 'matching', 'staged', 'committed', 'rolled_back', 'failed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INTG/transaction/confidential] Legacy data import or migration batch (mapping, validation, matching, staged commit, 30-day rollback)';

CREATE TABLE `import_row_issue` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `job_id` BINARY(16) NOT NULL,
  `row_no` INT UNSIGNED NOT NULL,
  `level` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `message` VARCHAR(1000) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `error_code` VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_import_row_issue_job_id` (`tenant_id`, `job_id`),
  CONSTRAINT `ck_import_row_issue__level` CHECK (`level` IN ('hard', 'soft', 'anomaly')),
  CONSTRAINT `ck_import_row_issue__status` CHECK (`status` IN ('open', 'in_progress', 'resolved', 'dismissed', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INTG/queue/confidential] Validation or matching issue on an import row';

CREATE TABLE `inbound_webhook` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `source` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `external_event_id` VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Provider event id — idempotency key',
  `signature_valid` BOOLEAN NOT NULL,
  `payload` JSON NOT NULL,
  `received_at` DATETIME(6) NOT NULL,
  `processed_at` DATETIME(6),
  `error` VARCHAR(1000) COLLATE utf8mb4_0900_ai_ci,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_inbound_webhook_source_external_event_id` (`tenant_id`, `source`, `external_event_id`),
  CONSTRAINT `ck_inbound_webhook__status` CHECK (`status` IN ('queued', 'sent', 'delivered', 'read', 'failed', 'retrying', 'abandoned', 'processed'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INTG/queue/confidential] Inbound webhook received (payment gateway, exam body, WhatsApp, state revenue) — signature verified, processed once';

CREATE TABLE `integration_connection` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `integration_code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'paystack, flutterwave, remita, nimc, waec, moodle, entra, ifmis …',
  `adapter_version` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `settings` JSON NOT NULL COMMENT 'Non-secret settings',
  `credentials_vault_ref` VARCHAR(255) COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Secrets in the vault only',
  `last_success_at` DATETIME(6),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_integration_connection_scope_node_id_integration_code` (`tenant_id`, `scope_node_id`, `integration_code`),
  CONSTRAINT `ck_integration_connection__status` CHECK (`status` IN ('active', 'inactive', 'retired'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INTG/config/internal] Configured integration (payment gateway, NIMC, exam body, LMS, SSO/SCIM, IFMIS, accounting, OCR engine, originality provider)';

CREATE TABLE `privacy_request` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `request_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `subject_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `subject_id` BINARY(16),
  `requester_name` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `identity_verified_at` DATETIME(6),
  `received_at` DATETIME(6) NOT NULL,
  `due_at` DATETIME(6) NOT NULL,
  `outcome` JSON COMMENT 'Per-entity actions (export, redact, crypto-shred, refused with basis)',
  `export_document_id` BINARY(16),
  `handled_by` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_privacy_request_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_privacy_request_handled_by` (`tenant_id`, `handled_by`),
  CONSTRAINT `ck_privacy_request__request_kind` CHECK (`request_kind` IN ('access', 'rectification', 'erasure', 'restriction', 'portability', 'objection')),
  CONSTRAINT `ck_privacy_request__subject_kind` CHECK (`subject_kind` IN ('learner', 'guardian', 'staff', 'provider_person', 'applicant', 'visitor')),
  CONSTRAINT `ck_privacy_request__status` CHECK (`status` IN ('draft', 'submitted', 'in_review', 'approved', 'rejected', 'cancelled', 'fulfilled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[INTG/transaction/restricted] Data-subject request (access, rectification, erasure respecting legal holds, restriction, portability, objection)';

-- ============================================================================
-- Domain AUD — Audit trail, chain anchors and the transactional outbox
-- ============================================================================

CREATE TABLE `audit_anchor` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `chain_id` BINARY(16) NOT NULL,
  `anchor_date` DATE NOT NULL,
  `last_chain_seq` BIGINT NOT NULL,
  `anchor_hash` BINARY(32) NOT NULL,
  `worm_object_key` VARCHAR(1024) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `verified_at` DATETIME(6),
  `verification_ok` BOOLEAN,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_audit_anchor_chain_id_anchor_date` (`tenant_id`, `chain_id`, `anchor_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[AUD/event/internal] Daily anchor of an audit chain written to write-once storage, and the nightly verification result';

CREATE TABLE `audit_chain_head` (
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `chain_id` BINARY(16) NOT NULL,
  `lane` SMALLINT NOT NULL,
  `last_seq` BIGINT NOT NULL,
  `last_hash` BINARY(32) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`chain_id`),
  KEY `ix_audit_chain_head_tenant` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[AUD/projection/internal] Head of an audit hash chain (last sequence and hash), locked FOR UPDATE by each writer to sequence the chain';

CREATE TABLE `audit_event` (
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `chain_id` BINARY(16) NOT NULL COMMENT 'Tenant id (or the platform chain id in the platform zone)',
  `chain_seq` BIGINT NOT NULL COMMENT 'Monotonic sequence within the chain',
  `occurred_at` DATETIME(6) NOT NULL,
  `event_id` BINARY(16) NOT NULL COMMENT 'UUID v7 of the event',
  `actor_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `actor_id` BINARY(16),
  `on_behalf_of_user_id` BINARY(16) COMMENT 'Agent X acting for Owner Y',
  `actor_grant_id` BINARY(16) COMMENT 'Active role-at-scope',
  `scope_node_id_at` BINARY(16) COMMENT 'Scope of the record at the time',
  `action` VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'e.g. learner.update, learner.nin.reveal, safeguarding_case.view, export.bulk',
  `record_kind` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `record_id` BINARY(16),
  `field_changes` JSON COMMENT '[{field, from, to}] — special-category values as hashes',
  `reason` VARCHAR(1000) COLLATE utf8mb4_0900_ai_ci,
  `purpose_code` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Required for restricted/special access',
  `approval_ref` BINARY(16),
  `correlation_id` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin,
  `ip` VARBINARY(16),
  `user_agent` VARCHAR(400) COLLATE utf8mb4_0900_ai_ci,
  `prev_hash` BINARY(32) NOT NULL,
  `hash` BINARY(32) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`chain_id`, `chain_seq`, `occurred_at`),
  KEY `ix_audit_event_record_kind_record_id` (`tenant_id`, `record_kind`, `record_id`),
  KEY `ix_audit_event_actor_id_occurred_at` (`tenant_id`, `actor_id`, `occurred_at`),
  CONSTRAINT `ck_audit_event__actor_kind` CHECK (`actor_kind` IN ('user', 'agent', 'api_client', 'system', 'platform_operator'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[AUD/event/restricted] Tamper-evident audit event (append-only, hash-chained per tenant and zone, partitioned by day)'
PARTITION BY RANGE COLUMNS (`occurred_at`) (
  PARTITION p20261001 VALUES LESS THAN ('2026-10-02 00:00:00'),
  PARTITION p20261002 VALUES LESS THAN ('2026-10-03 00:00:00'),
