-- ============================================================================
-- Domain HRM — Enterprise Human Resource Management Suite — establishment, employment, postings, leave, promotion, employee relations, separation, payroll elements and payroll integrity
-- ============================================================================

CREATE TABLE `cadre` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `code` VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `staff_category` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `is_teaching` BOOLEAN NOT NULL,
  `salary_structure_code` VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `entry_grade_level` SMALLINT NOT NULL,
  `max_grade_level` SMALLINT NOT NULL,
  `years_per_promotion` SMALLINT NOT NULL DEFAULT 3,
  `retirement_age` SMALLINT NOT NULL COMMENT '65 for teachers (Harmonised Retirement Age for Teachers in Nigeria Act 2022), 60 otherwise',
  `max_years_service` SMALLINT NOT NULL COMMENT '40 for teachers, 35 otherwise',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_cadre_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_cadre_scope_node_id_code` (`tenant_id`, `scope_node_id`, `code`),
  CONSTRAINT `ck_cadre__status` CHECK (`status` IN ('active', 'inactive', 'retired')),
  CONSTRAINT `ck_cadre__grades` CHECK (entry_grade_level <= max_grade_level)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[HRM/config/internal] Career cadre with progression and statutory retirement rule (e.g. Teacher, Education Officer, Principal, Lecturer)';

CREATE TABLE `employment_record` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `staff_post_id` BINARY(16) NOT NULL,
  `staff_id` BINARY(16) NOT NULL,
  `position_id` BINARY(16),
  `cadre_id` BINARY(16) NOT NULL,
  `employer_scope_id` BINARY(16) NOT NULL,
  `appointment_type` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `appointment_letter_ref` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin,
  `first_appointment_on` DATE NOT NULL COMMENT 'Date of first appointment into the service',
  `present_appointment_on` DATE NOT NULL,
  `confirmation_due_on` DATE,
  `confirmed_on` DATE,
  `salary_structure_id` BINARY(16) NOT NULL,
  `grade_level` SMALLINT NOT NULL,
  `step` SMALLINT NOT NULL,
  `last_promotion_on` DATE,
  `retirement_due_on` DATE COMMENT 'Earlier of retirement age and maximum years of service (cadre rule)',
  `retirement_basis` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `seat_key` BINARY(16) GENERATED ALWAYS AS (IF(`status` IN ('probation','confirmed','suspended','seconded'), `position_id`, NULL)) STORED COMMENT 'position_id while the post is active (one active holder per position)',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_employment_record_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_employment_record_staff_post_id` (`tenant_id`, `staff_post_id`),
  UNIQUE KEY `uq_employment_record_seat_key` (`tenant_id`, `seat_key`),
  KEY `ix_employment_record_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_employment_record_staff_id` (`tenant_id`, `staff_id`),
  KEY `ix_employment_record_position_id` (`tenant_id`, `position_id`),
  KEY `ix_employment_record_retirement_due_on` (`tenant_id`, `retirement_due_on`),
  KEY `ix_employment_record_employer_scope_id_status` (`tenant_id`, `employer_scope_id`, `status`),
  KEY `ix_employment_record_cadre_id` (`tenant_id`, `cadre_id`),
  KEY `ix_employment_record_salary_structure_id` (`tenant_id`, `salary_structure_id`),
  CONSTRAINT `ck_employment_record__appointment_type` CHECK (`appointment_type` IN ('first_appointment', 'transfer_of_service', 'secondment', 'contract', 'nysc', 'volunteer', 'private_hire')),
  CONSTRAINT `ck_employment_record__retirement_basis` CHECK (`retirement_basis` IS NULL OR `retirement_basis` IN ('age', 'length_of_service', 'contract_end', 'none')),
  CONSTRAINT `ck_employment_record__status` CHECK (`status` IN ('probation', 'confirmed', 'suspended', 'seconded', 'separated'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[HRM/master/confidential] Employment record of a staff post — appointment, confirmation, grade and step, position held and projected retirement';

CREATE TABLE `headcount_exercise` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `institution_id` BINARY(16) NOT NULL,
  `label` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'e.g. 2026-Q4',
  `method` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `starts_on` DATE NOT NULL,
  `ends_on` DATE NOT NULL,
  `conducted_by` BINARY(16) NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_headcount_exercise_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_headcount_exercise_institution_id_label` (`tenant_id`, `institution_id`, `label`),
  KEY `ix_headcount_exercise_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_headcount_exercise_conducted_by` (`tenant_id`, `conducted_by`),
  CONSTRAINT `ck_headcount_exercise__method` CHECK (`method` IN ('in_person', 'biometric', 'video')),
  CONSTRAINT `ck_headcount_exercise__status` CHECK (`status` IN ('draft', 'active', 'under_review', 'completed', 'closed', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[HRM/transaction/internal] Staff headcount (verification) exercise at an institution — in person, biometric or video';

CREATE TABLE `headcount_result` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `exercise_id` BINARY(16) NOT NULL,
  `staff_id` BINARY(16) NOT NULL,
  `staff_post_id` BINARY(16),
  `outcome` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `verified_at` DATETIME(6) NOT NULL,
  `evidence` JSON COMMENT 'Biometric match score, document seen, witness',
  `verifier_id` BINARY(16) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_headcount_result_exercise_id_staff_id` (`tenant_id`, `exercise_id`, `staff_id`),
  KEY `ix_headcount_result_staff_id` (`tenant_id`, `staff_id`),
  KEY `ix_headcount_result_staff_post_id` (`tenant_id`, `staff_post_id`),
  KEY `ix_headcount_result_verifier_id` (`tenant_id`, `verifier_id`),
  CONSTRAINT `ck_headcount_result__outcome` CHECK (`outcome` IN ('verified', 'absent_with_reason', 'absent_without_reason', 'not_on_nominal_roll', 'impersonation_suspected'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[HRM/event/confidential] Outcome for one staff member in a headcount exercise';

CREATE TABLE `hr_integrity_flag` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `staff_id` BINARY(16) NOT NULL,
  `employer_scope_id` BINARY(16),
  `flag_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `evidence` JSON NOT NULL COMMENT 'Matching records, dates and sources — never special-category data',
  `detected_at` DATETIME(6) NOT NULL,
  `run_label` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin,
  `payroll_hold` BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Set only by a person (A1)',
  `decided_by` BINARY(16),
  `decision_reason` TEXT,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `open_key` VARCHAR(120) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (IF(`status` IN ('open','in_progress'), CONCAT(`flag_kind`, ':', HEX(`staff_id`)), NULL)) STORED COMMENT 'kind:staff while open (one open flag per kind per staff member)',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_hr_integrity_flag_open_key` (`tenant_id`, `open_key`),
  KEY `ix_hr_integrity_flag_employer_scope_id_status` (`tenant_id`, `employer_scope_id`, `status`),
  KEY `ix_hr_integrity_flag_flag_kind` (`tenant_id`, `flag_kind`),
  KEY `ix_hr_integrity_flag_staff_id` (`tenant_id`, `staff_id`),
  KEY `ix_hr_integrity_flag_decided_by` (`tenant_id`, `decided_by`),
  CONSTRAINT `ck_hr_integrity_flag__flag_kind` CHECK (`flag_kind` IN ('shared_bank_account', 'shared_bvn', 'concurrent_public_posts', 'paid_after_separation', 'past_retirement_date', 'no_attendance_30_days', 'failed_headcount', 'post_without_position', 'grade_outside_position')),
  CONSTRAINT `ck_hr_integrity_flag__status` CHECK (`status` IN ('open', 'in_progress', 'resolved', 'dismissed', 'cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[HRM/queue/restricted] Payroll integrity flag across all employers in the state (ghost worker, double employment, pay after exit …)';

CREATE TABLE `position` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `position_code` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'POS-<institution code>-NNNN',
  `institution_id` BINARY(16) COMMENT 'NULL for ministry, board or LGA office positions',
  `org_unit_id` BINARY(16),
  `employer_scope_id` BINARY(16) NOT NULL COMMENT 'SUBEB, TESCOM, ministry, tertiary institution or private provider',
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `cadre_id` BINARY(16) NOT NULL,
  `staff_category` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `grade_level_min` SMALLINT NOT NULL,
  `grade_level_max` SMALLINT NOT NULL,
  `subject_id` BINARY(16) COMMENT 'Specialism for teaching positions',
  `education_levels` JSON,
  `funding` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `budget_line` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_position_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_position_position_code` (`tenant_id`, `position_code`),
  KEY `ix_position_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_position_institution_id_status` (`tenant_id`, `institution_id`, `status`),
  KEY `ix_position_employer_scope_id` (`tenant_id`, `employer_scope_id`),
  KEY `ix_position_subject_id` (`tenant_id`, `subject_id`),
  KEY `ix_position_org_unit_id` (`tenant_id`, `org_unit_id`),
  KEY `ix_position_cadre_id` (`tenant_id`, `cadre_id`),
  CONSTRAINT `ck_position__funding` CHECK (`funding` IN ('funded', 'unfunded', 'donor_funded', 'privately_funded')),
  CONSTRAINT `ck_position__status` CHECK (`status` IN ('proposed', 'approved', 'frozen', 'abolished')),
  CONSTRAINT `ck_position__grades` CHECK (grade_level_min <= grade_level_max)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[HRM/master/internal] Approved establishment position (one seat) at an institution, unit or office, with cadre, grade range and specialism';

CREATE TABLE `promotion_case` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `staff_id` BINARY(16) NOT NULL,
  `employment_record_id` BINARY(16) NOT NULL,
  `exercise_label` VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'e.g. 2026-PROMO',
  `from_grade_level` SMALLINT NOT NULL,
  `from_step` SMALLINT NOT NULL,
  `to_grade_level` SMALLINT NOT NULL,
  `to_step` SMALLINT NOT NULL,
  `eligibility` JSON NOT NULL COMMENT 'Years on grade, appraisal ratings, examination, discipline status — each with pass/fail',
  `exam_score` DECIMAL(6,3),
  `board_decision` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `decided_by` BINARY(16) COMMENT 'Human decision (board secretary)',
  `effective_on` DATE,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_promotion_case_staff_id_exercise_label` (`tenant_id`, `staff_id`, `exercise_label`),
  KEY `ix_promotion_case_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_promotion_case_employment_record_id` (`tenant_id`, `employment_record_id`),
  KEY `ix_promotion_case_decided_by` (`tenant_id`, `decided_by`),
  CONSTRAINT `ck_promotion_case__board_decision` CHECK (`board_decision` IS NULL OR `board_decision` IN ('approved', 'not_approved', 'deferred')),
  CONSTRAINT `ck_promotion_case__status` CHECK (`status` IN ('draft', 'submitted', 'in_review', 'approved', 'rejected', 'cancelled', 'fulfilled')),
  CONSTRAINT `ck_promotion_case__upward` CHECK (to_grade_level > from_grade_level OR (to_grade_level = from_grade_level AND to_step > from_step))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[HRM/transaction/confidential] Promotion case of a staff member in a promotion exercise (eligibility, examination, board decision, effective date)';

CREATE TABLE `salary_scale_point` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `structure_id` BINARY(16) NOT NULL,
  `grade_level` SMALLINT NOT NULL,
  `step` SMALLINT NOT NULL,
  `annual_basic_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `allowances` JSON COMMENT 'Standard allowances by element code, as amount or % of basic (housing, transport, rural posting …)',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_salary_scale_point_structure_id_grade_level_step` (`tenant_id`, `structure_id`, `grade_level`, `step`),
  CONSTRAINT `ck_salary_scale_point__positive` CHECK (annual_basic_minor > 0 AND grade_level BETWEEN 1 AND 17 AND step BETWEEN 1 AND 15)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[HRM/reference/internal] Grade level and step of a salary structure version with annual basic and standard allowances';

CREATE TABLE `salary_structure` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `code` VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'e.g. CONPSS, CONTISS, AB-TSS',
  `title` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `employer_scope_id` BINARY(16) COMMENT 'NULL = available to every employer in scope',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `effective_from` DATE NOT NULL,
  `version` INT UNSIGNED NOT NULL,
  `approval_instrument` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci COMMENT 'Circular or board resolution',
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_salary_structure_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_salary_structure_scope_node_id_code_version` (`tenant_id`, `scope_node_id`, `code`, `version`),
  KEY `ix_salary_structure_employer_scope_id` (`tenant_id`, `employer_scope_id`),
  CONSTRAINT `ck_salary_structure__status` CHECK (`status` IN ('draft', 'in_review', 'approved', 'published', 'superseded', 'retired', 'withdrawn'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[HRM/config/internal] Versioned salary structure (CONPSS, CONTISS, CONUASS, CONTEDISS, state teacher scales, private scales)';

CREATE TABLE `separation` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `staff_id` BINARY(16) NOT NULL,
  `staff_post_id` BINARY(16) NOT NULL,
  `separation_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `notice_on` DATE,
  `effective_on` DATE NOT NULL,
  `exit_checklist` JSON NOT NULL COMMENT 'Handover of classes (G9), assets, ID card, final pay, pension notification, access removal',
  `pension_notified_on` DATE,
  `recorded_by` BINARY(16) NOT NULL,
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_separation_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_separation_staff_id` (`tenant_id`, `staff_id`),
  KEY `ix_separation_effective_on` (`tenant_id`, `effective_on`),
  KEY `ix_separation_staff_post_id` (`tenant_id`, `staff_post_id`),
  KEY `ix_separation_recorded_by` (`tenant_id`, `recorded_by`),
  CONSTRAINT `ck_separation__separation_kind` CHECK (`separation_kind` IN ('resignation', 'retirement_statutory', 'retirement_voluntary', 'death', 'dismissal', 'termination', 'end_of_contract', 'transfer_of_service', 'abandonment')),
  CONSTRAINT `ck_separation__status` CHECK (`status` IN ('draft', 'submitted', 'in_review', 'approved', 'rejected', 'cancelled', 'fulfilled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[HRM/transaction/confidential] Separation from a post (resignation, retirement, death, dismissal, end of contract, transfer of service) with exit clearance';

CREATE TABLE `staff_bank_account` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `staff_id` BINARY(16) NOT NULL,
  `bank_code` VARCHAR(10) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'CBN bank code',
  `account_number_hmac` BINARY(32) NOT NULL COMMENT 'HMAC-SHA-256 lookup of account_number',
  `account_number_enc` VARBINARY(1024) NOT NULL COMMENT 'Envelope-encrypted account_number. NUBAN — envelope-encrypted',
  `account_number_last4` CHAR(4) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Last four characters of account_number for masked display',
  `account_name` VARCHAR(200) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `is_primary` BOOLEAN NOT NULL DEFAULT TRUE,
  `verified_via` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `verified_at` DATETIME(6),
  `requested_by` BINARY(16) NOT NULL,
  `approved_by` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_staff_bank_account_staff_id` (`tenant_id`, `staff_id`),
  KEY `ix_staff_bank_account_account_number_hmac` (`tenant_id`, `account_number_hmac`),
  KEY `ix_staff_bank_account_requested_by` (`tenant_id`, `requested_by`),
  KEY `ix_staff_bank_account_approved_by` (`tenant_id`, `approved_by`),
  CONSTRAINT `ck_staff_bank_account__verified_via` CHECK (`verified_via` IS NULL OR `verified_via` IN ('call_back', 'nibss_name_enquiry', 'document', 'none')),
  CONSTRAINT `ck_staff_bank_account__status` CHECK (`status` IN ('active', 'inactive', 'retired')),
  CONSTRAINT `ck_staff_bank_account__four_eyes` CHECK (approved_by IS NULL OR approved_by <> requested_by)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[HRM/master/restricted] Staff salary bank account (encrypted; lookup token for duplicate detection; dual approval and call-back on change)';

CREATE TABLE `staff_posting` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `order_number` VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `staff_id` BINARY(16) NOT NULL,
  `from_staff_post_id` BINARY(16),
  `to_position_id` BINARY(16) NOT NULL,
  `to_institution_id` BINARY(16),
  `posting_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `reason` TEXT NOT NULL,
  `effective_on` DATE NOT NULL,
  `coverage_impact` JSON COMMENT 'Class-subjects left without a teacher of record (G9) at the sending institution',
  `requested_by` BINARY(16) NOT NULL,
  `approved_by` BINARY(16),
  `workflow_instance_id` BINARY(16),
  `new_staff_post_id` BINARY(16),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_staff_posting_order_number` (`tenant_id`, `order_number`),
  KEY `ix_staff_posting_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_staff_posting_staff_id_status` (`tenant_id`, `staff_id`, `status`),
  KEY `ix_staff_posting_to_position_id` (`tenant_id`, `to_position_id`),
  KEY `ix_staff_posting_effective_on` (`tenant_id`, `effective_on`),
  KEY `ix_staff_posting_from_staff_post_id` (`tenant_id`, `from_staff_post_id`),
  KEY `ix_staff_posting_to_institution_id` (`tenant_id`, `to_institution_id`),
  KEY `ix_staff_posting_requested_by` (`tenant_id`, `requested_by`),
  KEY `ix_staff_posting_approved_by` (`tenant_id`, `approved_by`),
  KEY `ix_staff_posting_workflow_instance_id` (`tenant_id`, `workflow_instance_id`),
  KEY `ix_staff_posting_new_staff_post_id` (`tenant_id`, `new_staff_post_id`),
  CONSTRAINT `ck_staff_posting__posting_kind` CHECK (`posting_kind` IN ('first_posting', 'transfer', 'redeployment', 'secondment', 'promotion_posting', 'rationalisation', 'on_request', 'disciplinary')),
  CONSTRAINT `ck_staff_posting__status` CHECK (`status` IN ('draft', 'submitted', 'approved', 'effective', 'rejected', 'cancelled')),
  CONSTRAINT `ck_staff_posting__four_eyes` CHECK (approved_by IS NULL OR approved_by <> requested_by)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[HRM/transaction/confidential] Posting order — first posting, transfer, redeployment or secondment of a staff member between institutions and employers';

-- ============================================================================
-- Domain FCL — Fee-clearance due diligence — learner obligations register, clearance checks, admission decisions and disputes
-- ============================================================================

CREATE TABLE `clearance_check` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `learner_id` BINARY(16) NOT NULL,
  `requesting_institution_id` BINARY(16) NOT NULL,
  `purpose` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `basis` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `admission_application_id` BINARY(16) COMMENT 'ops-zone admission application',
  `learner_transfer_id` BINARY(16),
  `requested_by` BINARY(16) NOT NULL,
  `checked_at` DATETIME(6) NOT NULL,
  `coverage` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `result` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `obligations` JSON NOT NULL COMMENT 'Snapshot: obligation id, creditor, kind, amount, oldest due date, status',
  `total_outstanding_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `pattern_flags` JSON COMMENT 'e.g. repeat_unsettled_transfers (count, window)',
  `federation` JSON COMMENT 'National coverage: per state answered / not_on_network / unavailable, with match outcome',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_clearance_check_tenant_id_id` (`tenant_id`, `id`),
  KEY `ix_clearance_check_learner_id_checked_at` (`tenant_id`, `learner_id`, `checked_at`),
  KEY `ix_clearance_check_requesting_institution_id_checked_at` (`tenant_id`, `requesting_institution_id`, `checked_at`),
  KEY `ix_clearance_check_learner_transfer_id` (`tenant_id`, `learner_transfer_id`),
  CONSTRAINT `ck_clearance_check__purpose` CHECK (`purpose` IN ('admission', 'transfer', 're_enrolment', 'enquiry_with_consent')),
  CONSTRAINT `ck_clearance_check__basis` CHECK (`basis` IN ('admission_due_diligence', 'guardian_consent')),
  CONSTRAINT `ck_clearance_check__coverage` CHECK (`coverage` IN ('state', 'national')),
  CONSTRAINT `ck_clearance_check__result` CHECK (`result` IN ('clear', 'outstanding', 'disputed_only', 'protected'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FCL/event/restricted] Clearance check run for an incoming learner (purpose-bound, logged, visible to the family)';

CREATE TABLE `clearance_decision` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `check_id` BINARY(16) NOT NULL,
  `decision` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `protected_reason` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `reason` TEXT NOT NULL,
  `payment_plan_ref` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin,
  `decided_by` BINARY(16) NOT NULL COMMENT 'app_user, or the system for automatic protection',
  `decided_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_clearance_decision_check_id` (`tenant_id`, `check_id`),
  CONSTRAINT `ck_clearance_decision__decision` CHECK (`decision` IN ('admit', 'admit_with_payment_plan', 'defer_pending_settlement', 'admit_protected')),
  CONSTRAINT `ck_clearance_decision__protected_reason` CHECK (`protected_reason` IS NULL OR `protected_reason` IN ('public_basic_education', 'send', 'safeguarding', 'child_in_care', 'displaced', 'other_vulnerability')),
  CONSTRAINT `ck_clearance_decision__protection_reason` CHECK (decision <> 'admit_protected' OR protected_reason IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FCL/event/restricted] Human admission decision recorded on a clearance check (or the automatic protection of a learner)';

CREATE TABLE `clearance_exchange_query` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `direction` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `query_ref` BINARY(16) NOT NULL COMMENT 'JWS jti shared by both states (replay protection)',
  `counterpart_state_code` VARCHAR(6) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `clearance_check_id` BINARY(16) COMMENT 'Outbound: the check the query belongs to',
  `learner_id` BINARY(16) COMMENT 'Outbound: the subject; inbound: the matched local learner',
  `purpose` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `identifiers_used` JSON NOT NULL COMMENT 'Which keys were sent: glid, nin_token, demographics',
  `match_outcome` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `obligations` JSON COMMENT 'Summary sent (inbound) or received (outbound)',
  `total_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `requesting_institution` VARCHAR(300) COLLATE utf8mb4_0900_ai_ci COMMENT 'Inbound: who asked',
  `kid` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin COMMENT 'Key that signed the counterpart''s message',
  `latency_ms` INT,
  `error` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin,
  `occurred_at` DATETIME(6) NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_clearance_exchange_query_direction_query_ref_counter_35830eac` (`tenant_id`, `direction`, `query_ref`, `counterpart_state_code`),
  KEY `ix_clearance_exchange_query_learner_id_occurred_at` (`tenant_id`, `learner_id`, `occurred_at`),
  KEY `ix_clearance_exchange_query_counterpart_state_code_occurred_at` (`tenant_id`, `counterpart_state_code`, `occurred_at`),
  KEY `ix_clearance_exchange_query_clearance_check_id` (`tenant_id`, `clearance_check_id`),
  CONSTRAINT `ck_clearance_exchange_query__direction` CHECK (`direction` IN ('outbound', 'inbound')),
  CONSTRAINT `ck_clearance_exchange_query__purpose` CHECK (`purpose` IN ('admission', 'transfer', 're_enrolment', 'enquiry_with_consent')),
  CONSTRAINT `ck_clearance_exchange_query__match_outcome` CHECK (`match_outcome` IN ('matched', 'possible_match', 'not_found', 'refused', 'unavailable', 'not_on_network'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FCL/event/restricted] Cross-state clearance exchange message — outbound query or inbound query answered (logged in both states)';

CREATE TABLE `learner_obligation` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `learner_id` BINARY(16) NOT NULL,
  `creditor_institution_id` BINARY(16) NOT NULL,
  `creditor_tenant_id` BINARY(16) NOT NULL COMMENT 'Operating tenant whose ledger holds the invoices',
  `obligation_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `payer_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `periods` JSON COMMENT 'Billing periods covered, e.g. 2025/26-T2, 2025/26-T3',
  `amount_outstanding_minor` BIGINT NOT NULL COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `oldest_due_on` DATE NOT NULL,
  `evidence` JSON NOT NULL COMMENT 'Invoice numbers and content hashes, or document ids for manual claims',
  `evidence_hash` BINARY(32) NOT NULL COMMENT 'SHA-256 of the canonical evidence',
  `source` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `published_by` BINARY(16) NOT NULL,
  `published_at` DATETIME(6) NOT NULL,
  `reconfirm_by` DATE NOT NULL COMMENT 'Expires if the creditor does not reconfirm (default 90 days)',
  `last_checked_at` DATETIME(6),
  `settled_at` DATETIME(6),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `open_key` VARCHAR(120) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (IF(`status` IN ('outstanding','payment_plan','disputed'), CONCAT(HEX(`learner_id`), ':', HEX(`creditor_institution_id`), ':', `obligation_kind`), NULL)) STORED COMMENT 'learner:creditor:kind while open',
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_learner_obligation_tenant_id_id` (`tenant_id`, `id`),
  UNIQUE KEY `uq_learner_obligation_open_key` (`tenant_id`, `open_key`),
  KEY `ix_learner_obligation_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_learner_obligation_learner_id_status` (`tenant_id`, `learner_id`, `status`),
  KEY `ix_learner_obligation_creditor_institution_id_status` (`tenant_id`, `creditor_institution_id`, `status`),
  KEY `ix_learner_obligation_reconfirm_by` (`tenant_id`, `reconfirm_by`),
  CONSTRAINT `ck_learner_obligation__obligation_kind` CHECK (`obligation_kind` IN ('tuition_fees', 'boarding', 'examination_fees', 'transport', 'meals', 'books_and_materials', 'uniform', 'development_levy', 'damaged_property', 'library', 'other_dues')),
  CONSTRAINT `ck_learner_obligation__payer_kind` CHECK (`payer_kind` IN ('learner', 'family', 'guardian', 'sponsor', 'funder', 'government', 'employer', 'institution')),
  CONSTRAINT `ck_learner_obligation__source` CHECK (`source` IN ('ledger', 'manual_with_evidence')),
  CONSTRAINT `ck_learner_obligation__status` CHECK (`status` IN ('outstanding', 'payment_plan', 'disputed', 'settled', 'written_off', 'waived', 'expired', 'withdrawn')),
  CONSTRAINT `ck_learner_obligation__positive` CHECK (amount_outstanding_minor > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FCL/transaction/restricted] Outstanding obligation of a learner''s payer to an institution (fees or other dues), published from the creditor''s ledger';

CREATE TABLE `obligation_dispute` (
  `id` BINARY(16) NOT NULL COMMENT 'Primary key: UUID v7 (time-ordered) stored as BINARY(16) without byte swap',
  `tenant_id` BINARY(16) NOT NULL COMMENT 'Owning tenant (zones with tenant_column = true)',
  `scope_node_id` BINARY(16) NOT NULL COMMENT 'Owning governance scope node (entities with scope: owned); subtree visibility through scope_closure',
  `obligation_id` BINARY(16) NOT NULL,
  `raised_by_kind` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `raised_by` BINARY(16) NOT NULL,
  `grounds` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `statement` TEXT NOT NULL,
  `evidence_document_ids` JSON,
  `due_by` DATE NOT NULL COMMENT 'Resolution service level (default 10 school days)',
  `resolver_scope_id` BINARY(16) NOT NULL COMMENT 'LGA or state node that decides',
  `resolution` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin,
  `resolved_amount_minor` BIGINT COMMENT '(minor units)',
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `resolved_by` BINARY(16),
  `resolved_at` DATETIME(6),
  `status` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'UTC time the row was written',
  `created_by` BINARY(16) COMMENT 'Actor: app_user.id or service_identity.id (agents, integrations)',
  `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT 'UTC time of last change (mutable entities only)',
  `updated_by` BINARY(16) COMMENT 'Actor of last change (mutable entities only)',
  `row_version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Optimistic-lock counter; exposed as the API ETag (mutable entities only)',
  PRIMARY KEY (`id`),
  KEY `ix_obligation_dispute_scope` (`tenant_id`, `scope_node_id`),
  KEY `ix_obligation_dispute_obligation_id` (`tenant_id`, `obligation_id`),
  KEY `ix_obligation_dispute_resolver_scope_id_status` (`tenant_id`, `resolver_scope_id`, `status`),
  KEY `ix_obligation_dispute_resolved_by` (`tenant_id`, `resolved_by`),
  CONSTRAINT `ck_obligation_dispute__raised_by_kind` CHECK (`raised_by_kind` IN ('guardian', 'learner', 'admitting_institution', 'creditor')),
  CONSTRAINT `ck_obligation_dispute__grounds` CHECK (`grounds` IN ('already_paid', 'amount_wrong', 'not_liable', 'waiver_granted', 'statute_barred', 'protected_learner', 'other')),
  CONSTRAINT `ck_obligation_dispute__resolution` CHECK (`resolution` IS NULL OR `resolution` IN ('upheld', 'partly_upheld', 'rejected', 'withdrawn')),
  CONSTRAINT `ck_obligation_dispute__status` CHECK (`status` IN ('open', 'in_progress', 'on_hold', 'closed', 'transferred'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='[FCL/transaction/restricted] Dispute of a published obligation by the family, the admitting institution or the creditor (resolved by LGA or state)';


